 7     int n,ma,mb;
 8     cin >> n >> ma >> mb;


 9

10     for(int i=0;i<n;++i){

11         cin >> a[i] >> b[i] >> c[i];

12     }


13

14     for(int i = 0; i <= n; ++i){

15         for(int ca = 0; ca <= nmax*abmax; ++ca){

16             for(int cb = 0; cb <= nmax*abmax; ++cb){

17                 dp[i][ca][cb]=inf;

18             }

19         }

20     }


21

22     dp[0][0][0]=0;


