C : Splitting Pile

 N 枚のカードに書かれた数の総和をX とする．カードの山の先頭i 枚のカードに書かれた数の

総和がxi であったとすると，残ったカードたちに書かれた数の和yi はX −xi であり，|yi −xi|
は|X −2xi| となる．
  1 からN −1 までの全てのi について|X −2xi| を試せばよい．これはO(N) で実行可能であ

り，十分高速である．

#include <algorithm>

#include <iostream>

#include <vector>

using namespace std;

int main(){

    int n;

    long long X=0,x=0,ans=1000000000000000000LL;

    cin>>n;

    vector<long long> a(n);

    for(int i=0;i<n;i++){

        cin>>a[i];

        X+=a[i];

    }

    for(int i=0;i<n;i++){

        x+=a[i];

        if(i+1<n)ans=min(ans,abs(X-2*x));

    }

    cout<<ans<<endl;

}





