C:  Write and Erase

 　まず、どのような場合に数が最後に紙に書かれており、どのような場合に書かれてい
ないかを考えてみる。
　Ai に一度しか登場しなければ、その数は最後まで紙に残る。Ai に二度登場すれば、
その数は最後には紙に残っていない。同様に考えていくと、Ai に偶数回登場する数は最
後に紙には書かれていないが、奇数回登場する数は最後に紙に書かれているとわかる。
　よって、求めるのは奇数回登場する数が何種類あるかで良いことがわかる。
　N は最大で100000、Ai は最大で109 であり、O(N2) 回かけて数えたり、109 個の
フラグを持つような手法はとることができず、異なる方法を考える必要がある。
　Ai をソートすると、同じ数が隣り合うように並べ替えられる。これを左から順にみて
いくと、奇数回登場する数が何種類あるかを数えることができる。
　ソート部分がO(NlogN) 、左から見ていく部分がO(N) より、これで間に合う。
　また、C++におけるset のようなデータ構造を用いて紙に書かれている数を持っておき、
実際にシミュレーションしても解くことができる。


#include <cstdio >
#include <algorithm >
using namespace std;
int N,ptr ,res;
int A[100000];
int main ()
{
        scanf("%d" ,&N);
        for(int i=0;i<N;i++) scanf("%d" ,&A[i]);
        sort(A,A+N);
        while(ptr <N)
          {
                  int cc=A[ptr],f=0;
                 while(ptr <N&&A[ptr ]==cc)f++,ptr ++;
                 res+=f%2;
          }
        printf("%d\n",res);
}

D:   joisino’s travel

 　N が200 以下なので、町と町の間の距離はワーシャルフロイド法で求めて問題ない。
　そして、ri の並べ方だが、こちらもR が8 以下なので、すべての順列について試して
みることができる。
　順列の生成方法はいろいろ考えられるが、深さ優先探索を用いても十分間に合う。
　また、C++におけるnext permutation のような標準ライブラリを用いて解くのもよい
だろう。


#include <cstdio >
using namespace std;
#define INF (1<<29)

int N,M,R;
int d[201][201];
int r[9];
int A,B,C;
int res;
bool used [9];


                                      2

void dfs(int c,int las ,int dist)
{
        if(c==R+1)
          {
                 if(res >dist)res=dist;
                 return;
          }
        for(int i=1;i<=R;i++)if(! used[i])
          {
                 used[i]= true;
                 if(las ==-1) dfs(c+1,i ,0);
                 else dfs(c+1,i,dist+d[r[las ]][r[i]]);
                 used[i]= false;
          }
}



int main ()
{
        scanf("%d%d%d" ,&N,&M,&R);
        for(int i=1;i<=N;i++) for(int j=1;j<=N;j++)if(i!=j)d[i][j]=INF;
        for(int i=1;i<=R;i++) scanf("%d" ,&r[i]);
        for(int i=1;i<=M;i++)
          {
                scanf("%d%d%d" ,&A,&B,&C);
                if(d[A][B]>C)d[A][B]=d[B][A]=C;
          }
        for(int k=1;k<=N;k++)
                 for(int i=1;i<=N;i++)
                         for(int j=1;j<=N;j++)
                                if(d[i][j]>d[i][k]+d[k][j])
                                        d[i][j]=d[i][k]+d[k][j];
        res=INF;
         dfs (1,-1,0);
        printf("%d\n",res);
}





