#include <iostream >
using
namespace
std;
int main () {
int A, B; cin >> A >> B;
if (A * B % 2 == 1) {
cout << "Yes" << endl;
}
else {
cout << "No" << endl;
}
}
しかし、この事実に気付かなくとも全てのC = 1, 2, 3 に対してA × B × C の偶奇を調べる方法でも正答
できます。その場合のC++ による実装例は次のようになります。
