B: Shiritori
問題文の条件を言い換えると、次のようになります。
1. 1 ≤i ≤n −1 を満たす各i についてWi の最後の文字とWi+1 の最初の文字が等しい
2. 1 ≤i < j ≤n を満たす各i, j についてWi̸ = Wj
これをC++ で実装した例を以下に示します。
#include <iostream >
#include <vector >
using
namespace
std;
bool
solve(const vector <string >& W) {
const int n = W.size ();
// condition 1
for (int i = 0; i < n-1; ++i) {
if (W[i]. back () != W[i+1]. front ()) {
return
false;
}
}
// condition 2
for (int i = 0; i < n; ++i) {
for (int j = i+1; j < n; ++j) {
if (W[i] == W[j]) {
return
false;
}
}
}
return
true;
}
vector <string > input () {
int n; cin >> n;
vector <string > W(n);
for (int i = 0; i < n; ++i) {
cin >> W[i];
}
return W;
}

int main () {
const vector <string > W = input ();
if (solve(W)) {
cout << "Yes" << endl;
}
else {
cout << "No" << endl;
}
}
余談: std::set を用いてより高速に判定することもできますが、今回の場合はこれで十分です。

A: Maximize the Formula
数式XY + Z とZ + XY の値は同じなので、XY + Z の形のみを考えることにします。さらに、XY + Z
とXZ +Y の値は変わりません。従って、作れる数式の値は10×X +Y +Z, X +10×Y +Z, X +Y +10×Z
の3 通りです。これらの最大値が答えになるので、C++ での実装例は次のようになります。
#include <iostream >
#include <algorithm >
using
namespace
std;
int main () {
int A, B, C; cin >> A >> B >> C;
int ans = max <int >({
10 * A + B + C,
A + 10 * B + C,
A + B + 10 * C,
});
cout << ans << endl;
}
さらに考察すると、X, Y, Z のうち最大のものに10 をかける場合が最大になります。これをC++ で実装
すると、例えば次のようになります。
#include <iostream >
#include <algorithm >
using
namespace
std;
int main () {
int A, B, C; cin >> A >> B >> C;
int mx = max({A, B, C});

int ans = A + B + C + 9 * mx;
cout << ans << endl;
}

B: 1 Dimensional World’s Tale
X とxi, Y とyi は同一視できるので、xN+1 = X, yM+1 = Y とします。すると、Z が満たすべき条件は
次のようになります。
• x1, x2, ..., xN+1 < Z
• y1, y2, ..., yM+1 ≥Z
このようなZ は存在するならx1 (または−100) より大きく、y1 (または100) 以下のはずなので、Z =
−100, −99, ..., 100 と順に条件を満たすものがあるか調べて解くことができます。これをC++ で実装する
と、例えば次のようになります。
#include <iostream >
#include <vector >
using
namespace
std;
bool
is_war(const vector <int >& x, const vector <int >& y) {
for (int Z =
-100; Z <= 100; ++Z) {
bool
is_ok = true;
for (int i = 0; i < x.size (); ++i) {
if (x[i] >= Z) is_ok = false;
}
for (int i = 0; i < y.size (); ++i) {
if (y[i] < Z) is_ok = false;
}
if (is_ok) return
false;
}
return
true;
}
int main () {
int N, M; cin >> N >> M;
vector <int > x(N+1), y(M+1);
cin >> x[0] >> y[0];
for (int i = 0; i < N; ++i) {
cin >> x[i+1];
}
for (int i = 0; i < M; ++i) {
cin >> y[i+1];

}
if (is_war(x, y)) {
cout << "War" << endl;
}
else {
cout << "No War" << endl;
}
}
他の考え方もあります。xi ≥yj なるi, j が存在すれば、条件を満たすZ は存在しません(存在し
たとするとxi < Z ≤yj となって矛盾します)。逆に、全てのi, j についてxi < yj が成立すれば、
Z = min{y1, y2, ..., yM+1} とすることで条件を満たします。
すなわち、全てのi, j についてxi < yj であるかを調べる方法や、Z = min{y1, y2, ..., yM+1} とし
て条件を満たすかどうかを調べる方法があります。前者については、代わりにmax{x1, x2, ..., xN+1} <
min{y1, y2, ..., yM+1} であるかどうか調べてもよく、上の実装例のis war 関数をこの方法で実装すると次の
ようになります。
#include <algorithm >
bool
is_war(const vector <int >& x, const vector <int >& y) {
return *max_element(x.begin(), x.end ())
>= *min_element(y.begin(), y.end ());
}

