mod = 1000000007

def fast_pow(x, k):
  res = 1
  while k:
    if k & 1:
      res = res * x % mod
    x = x * x % mod
    k >>= 1
  return res

N, M, K = map(int, input().split())
S = M + K
dp = [fast_pow(i, K) for i in range(S + 1)]
for _ in range(M):
  for i in range(1, S + 1):
    dp[i] = (dp[i - 1] + dp[i]) % mod

invfac = [0] * (S + 1)
fac = 1
for i in range(1, S + 1):
  fac = fac * i % mod
invfac[-1] = pow(fac, mod - 2, mod)
for i in reversed(range(S)):
  invfac[i] = invfac[i + 1] * (i + 1) % mod

N %= mod

L = [1] * (S + 1)
for i in range(S):
  L[i + 1] = L[i] * (N - i) % mod
R = [1] * (S + 1)
for i in reversed(range(1, S + 1)):
  R[i - 1] = R[i] * (N - i) % mod

answer = 0
for i in range(S + 1):
  tmp = dp[i] * L[i] % mod * R[i] % mod * invfac[i] % mod * invfac[S - i] % mod
  if S % 2 == i % 2:
    answer += tmp
  else:
    answer -= tmp

print(answer % mod)

