int main(){
    int N,M,Q; cin >> N >> M >> Q;
    vector<int> A(M),B(M),S(M),T(M);
    vector<vector<pair<int,int>>> bus(N+1);
    for(int i=0; i<M; i++){
        cin >> A[i] >> B[i] >> S[i] >> T[i];
        bus[A[i]].push_back(make_pair(S[i],i));
    }
    for(auto &p: bus) sort(p.begin(),p.end());
    vector<vector<int>> edge(M);
    vector<bool> isroot(M);
    for(int i=0; i<M; i++){
        auto itr = lower_bound(bus[B[i]].begin(),bus[B[i]].end(),make_pair(T[i],-1));
        if(itr == bus[B[i]].end()) isroot[i] = true;
        else edge[(*itr).second].push_back(i);
    }
    vector<int> X(Q),Y(Q),Z(Q);
    vector<vector<int>> ans(Q),mem(M);
    for(int i=0; i<Q; i++){
        cin >> X[i] >> Y[i] >> Z[i];
        auto itr = lower_bound(bus[Y[i]].begin(),bus[Y[i]].end(),make_pair(X[i],-1));
        if(itr == bus[Y[i]].end() || Z[i] <= (*itr).first) ans[i] = {Y[i]};
        else mem[(*itr).second].push_back(i);
    }
    vector<int> time,city;
    function<void(int)> dfs = [&](int now){
        time.push_back(T[now]);
        time.push_back(S[now]);
        city.push_back(B[now]);
        city.push_back(A[now]);
        for(auto i: mem[now]){
            int idx = lower_bound(time.rbegin(),time.rend(),Z[i])-time.rbegin();
            if(idx == time.size()) ans[i] = {*city.begin()};
            else if(idx%2 == 0) ans[i] = {*(city.rbegin()+idx)};
            else ans[i] = {*(city.rbegin()+idx-1),*(city.rbegin()+idx)};
        }
        for(auto next: edge[now]){
            dfs(next);
        }
        time.pop_back();
        time.pop_back();
        city.pop_back();
        city.pop_back();
    };
    for(int i=0; i<M; i++){
        if(!isroot[i]) continue;
        dfs(i);
    }
    for(auto p: ans){
        for(auto q: p) cout << q << " ";
        cout << endl;
    }
}

#include <bits/stdc++.h>
using namespace std;

#define N (1<<16)
#define K 16
#define MOD 998244353
#define ll long long
#define rep(i, n) for(int i = 0; i < n; ++i)
#define rep2(i, a, b) for(int i = a; i <= b; ++i)

ll modpow(ll x, int a) {
	x %= MOD;
	ll re = 1;
	while (a > 0) {
		if (a % 2 == 1)re = (re*x) % MOD;
		x = (x*x) % MOD;
		a /= 2;
	}
	return re;
}

ll inv(ll x) {
	return modpow(x, MOD - 2);
}

ll func(ll x, int n) {
	x %= MOD;
	if (x == 0)return (ll)0;
	if (x == 1)return (ll)n;
	ll re = modpow(x, n) - 1;
	re = (re*x) % MOD;
	re = (re*inv(x - 1)) % MOD;
	return re;
}


int main(void) {
	int p2[K];
	p2[0] = 1;
	rep(i, K - 1)p2[i + 1] = p2[i] * 2;
	int n, k, d;
	ll a[N];
	rep(i, N)a[i] = 0;
	ll x;
	ll ans = 0;

	cin >> n >> k;
	rep(i, k) {
		cin >> x;
		a[x] = 1;
	}
	rep(kk, K) {
		rep(i, p2[K - kk - 1]) {
			d = p2[kk + 1] * i;
			rep(j, p2[kk]) {
				x = (a[d + j] - a[d + p2[kk] + j] + MOD) % MOD;
				a[d + j] = (a[d + j] + a[d + p2[kk] + j]) % MOD;
				a[d + p2[kk] + j] = x;
			}
		}
	}
	rep(i, N)a[i] = func(a[i], n);
	rep(kk, K) {
		rep(i, p2[K - kk - 1]) {
			d = p2[kk + 1] * i;
			rep(j, p2[kk]) {
				x = (a[d + j] - a[d + p2[kk] + j] + MOD) % MOD;
				a[d + j] = (a[d + j] + a[d + p2[kk] + j]) % MOD;
				a[d + p2[kk] + j] = x;
			}
		}
	}

	rep2(i, 1, N - 1)ans += a[i];
	ans %= MOD;
	ans = (ans * (inv((ll)N))) % MOD;
	cout << ans << endl;

	return 0;
}

