    es.emplace_back(a, b);
    p[a][b].resize(T + 1);
    for (int j = 1; j <= T; j++) cin >> x, p[a][b][j] = x;
  }
  for (int i = 0; i < N; i++) d[i].resize(T + 1);
  d[0][0] = 1;
  online_convolution(0, T + 1);
