vector<pair<int, int>> vec;
bool used[20];

int calc()
{
  if(vec.size() == n){
    int ret = 0;
    for(auto p : vec) ret ^= (a[p.first][p.second]);
    return ret;
  }

  int l;
  for(int i = 1; i <= 2*n; i++){
    if(!used[i]){
      l = i;
      break;
    }
  }
  used[l] = true;

  int ret = 0;
  for(int i = 1; i <= 2*n; i++){
    if(!used[i]){
      vec.push_back({l, i}), used[i] = true;
      ret = max(ret, calc());
      vec.pop_back(), used[i] = false;
    }
  }

  used[l] = false;
  return ret;
}

