use proconio::{input, source::line::LineSource};

fn main() {
    let stdin = stdin();
    let mut source = LineSource::new(BufReader::new(stdin.lock()));

    input! {
        from &mut source,
        n: usize,
    }

    let mut rem: BTreeSet<_> = (1..=2 * n + 1).collect();
    for _ in 0..=n {
        let x = *rem.iter().next().unwrap();
        println!("{}", x);
        stdout().flush().unwrap();
        rem.remove(&x);
        input! {
