int main(){
    int N, M, K, S, T, X;
    cin >> N >> M >> K >> S >> T >> X;
    S--; T--; X--;
    vector<pair<int, int>> edge(M);
    for(auto& [U, V] : edge){
        cin >> U >> V;
        U--; V--;
    }
    vector dp(K + 1, vector(N, array<Modint, 2>{0, 0}));
    dp[0][S][0] = 1;
