void dfs(int v)
{
  used[v] = true;
  ans.push_back(v), s[v] ^= 1;
  for(auto u : G[v]){
    if(used[u]) continue;
    dfs(u);
    ans.push_back(v), s[v] ^= 1;
    if(s[u] == 1){
      ans.push_back(u), s[u] ^= 1;
      ans.push_back(v), s[v] ^= 1;
    }
  }
}

