        }
        if(ep[i-1]){
            if(abs(b[i-1]-a[i])<=k)dp[i]=true;
            if(abs(b[i-1]-b[i])<=k)ep[i]=true;
        }
    }

    //答え
    if(dp[n]||ep[n])cout<<"Yes"<<endl;
    else cout<<"No"<<endl;

    return 0;
