        }
        if (k % (d + f) < d) {
            aoki += e;
        }
    }
    if (takahashi > aoki) {
        cout << "Takahashi\n";
    } else if (takahashi < aoki) {
        cout << "Aoki\n";
    } else {
        cout << "Draw\n";
    }
    return 0;
}

def solve(a, b, c, x):
  q = x // (a + c)
  r = x % (a + c);
  return (q * a + min(a, r)) * b;

