    if (x == w.size - 1) {
      return if (a[y][x] == h[y] - a[y][0] - a[y][1]) 1 else 0 // 最後の1マスまで書き込めた
    }
    return dfs(x + 1, y, a, w, h)
  }
  if (x == w.size - 1) {
    a[y][x] = h[y] - a[y][0] - a[y][1]
    if (a[y][x] <= 0) return 0 // 書き込み方が条件を満たさなかった
    return dfs(0, y + 1, a, w, h)
  }
  return (1..30).map { // 自由に書き込めるマス、全探索する
