fun pow(a: Long, b: Long): Long {
  var ans = 1L // 答え
  var mul = a // a^bitの値
  var bit = 1L // 2冪の値を取る
  while (b >= bit) {
    if ((b and bit) != 0L) ans *= mul // 2進数上で1となる桁の部分をansに足していく
    bit = bit shl 1
    mul *= mul
  }
  return ans
}

