      int run = 0; // 得た得点
      while(N --> 0) {
        int A = sc.nextInt();
        bitset.set(0);
        for (int i = bitset.length(); (i = bitset.previousSetBit(i - 1)) >= 0; ) { // https://docs.oracle.com/javase/jp/8/docs/api/java/util/BitSet.html#previousSetBit-int- に、この書き方が推奨されている
          bitset.set(i, false);
          if (i + A < 4) bitset.set(i + A); // 進塁
          else ++ run;
        }
      }
      out.println(run);
    }
  }
}

