          val a31 = w[0] - a11 - a21
          if (a31 <= 0) continue
          for (a22 in WRITE) {
            val a23 = h[1] - a21 - a22
            if (a23 <= 0) continue
            val a32 = w[1] - a12 - a22
            if (a32 <= 0) continue
            val a33 = h[2] - a31 - a32
            if (a33 != w[2] - a13 - a23 || a33 <= 0) continue
            ++ ans
          }
        }
      }
    }
    println(ans)
  }
}

