      set } // now[i]は現時点で頂点iから辿れる頂点集合
    for (e in edges) {
      val next = Array(N) {i -> // next[i]は辺を一つ追加したときに頂点iから辿れる頂点集合
        val set = now[i].clone() as BitSet
        if (now[i][e.from]) set.or(now[e.to])
        set
      }
      if (next.any {it.cardinality() == N}) { // 全ての頂点に辿れる頂点を発見したら終わり
        println(e.weight)
        return
      }
      now = next
    }
  }
}

