      adult.size + (adult.binarySearch(2 * x - 1) + 1) } // adultかつW[i]≧xの数、補集合を数えている
    println((0..N)
      .map {if (it == N) 1_000_000_001 else W[it]}
      .map(f)
      .max())
  }
