    Trampoline(long x, long y, long P) {
      this.x = x;
      this.y = y;
      this.P = P;
    }
    long needS(Trampoline target) {
      return (Math.abs(x - target.x) + Math.abs(y - target.y) + P - 1) / P;
    }
  }
}

