#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(int i = 0; i < n; ++i)
#define N 300010
#define INF (int)1e+9

int main(void) {
	int n, m;
	bool ex[N];
	bool used[N];
	rep(i, N)ex[i] = false;
	vector<int>e[N];
	int d[2][N];
	queue<int>q;
	int mn[2];
	int x, y;

	cin >> n >> m;
	for (int i = 0; i < m; i++) {
		cin >> x >> y;
		if (x == 0)ex[y - 1] = true;
		else {
			e[x - 1].push_back(y - 1);
			e[y - 1].push_back(x - 1);
		}
	}

	for (int i = 0; i < n; i++)d[0][i] = INF;
	for (int i = 0; i < n; i++)used[i] = false;
	mn[0] = INF;
	used[0] = true;
	d[0][0] = 0;
	q.push(0);
	while (!q.empty()) {
		x = q.front();
		q.pop();
		if (ex[x])mn[0] = min(mn[0], d[0][x]);
		y = e[x].size();
		for (int i = 0; i < y; i++) {
			if (!used[e[x][i]]) {
				used[e[x][i]] = true;
				d[0][e[x][i]] = d[0][x] + 1;
				q.push(e[x][i]);
			}
		}
	}

	for (int i = 0; i < n; i++)d[1][i] = INF;
	for (int i = 0; i < n; i++)used[i] = false;
	mn[1] = INF;
	used[n - 1] = true;
	d[1][n - 1] = 0;
	q.push(n - 1);
	while (!q.empty()) {
		x = q.front();
		q.pop();
		if (ex[x])mn[1] = min(mn[1], d[1][x]);
		y = e[x].size();
		for (int i = 0; i < y; i++) {
			if (!used[e[x][i]]) {
				used[e[x][i]] = true;
				d[1][e[x][i]] = d[1][x] + 1;
				q.push(e[x][i]);
			}
		}
	}

	for (int i = 0; i < n; i++) {
		x = min(d[0][n - 1], mn[0] + mn[1] + 2);
		x = min(x, mn[0] + 1 + d[1][i]);
		x = min(x, mn[1] + 1 + d[0][i]);
		if (x < INF)cout << x;
		else cout << -1;
		if (i < (n - 1))cout << " ";
		else cout << endl;
	}

	return 0;
}

