    val child = (0 until N)
      .filter {S[it] == '0'}
      .map {2 * W[it]} // binarySearchは同一キーの場合の答えが規定されないので、隙間を空けて被らないようにする
      .sorted()
    val adult = (0 until N)
      .filter {S[it] == '1'}
      .map {2 * W[it]} // binarySearchは同一キーの場合の答えが規定されないので、隙間を空けて被らないようにする
      .sorted()
    val f = {x: Int -> 
      -(child.binarySearch(2 * x - 1) + 1) + // childかつW[i]<xの数
      adult.size + (adult.binarySearch(2 * x - 1) + 1) } // adultかつW[i]≧xの数、補集合を数えている
    println((0..N)
      .map {if (it == N) 1_000_000_001 else W[it]}
      .map(f)
