      long ans = Long.MAX_VALUE; // 最小化なのでminを取る なので単位元である∞を入れておく
      for (int x = 1;x <= Math.min(N, X);++ x) { // Xより大きいステージは挑めない
        long A = sc.nextLong(), B = sc.nextLong(); // 後でX*Bを求める、32bitより大きくなるためlongで受け取っておく
