fun solve(sc: FastScanner, out: PrintWriter) {
  val N = sc.nextInt()
  val Q = sc.nextInt()
  val S = sc.next()
  var p = 0 // この位置から始める
  repeat(Q) {
    val query = sc.nextInt()
    val x = sc.nextInt()
    if (query == 1) p = (p + N - x) % N // xを引くこととN-xを足すことはmod N上で等しい
    else out.println(S[(p + x - 1) % N])
  }
}

class FastScanner { // 正直、ただ移植してるだけになってて良くないかも
  private val `in` = System.`in`
  private val buffer = ByteArray(8192)
  private var ptr = 0
  private var buflen = 0
  private fun hasNextByte(): Boolean {
    if (ptr < buflen) return true
    ptr = 0
    try {
      buflen = `in`.read(buffer)
    } catch (e: IOException) {
      e.printStackTrace()
    }
    return buflen > 0
  }

  private fun readByte(): Byte = if (hasNextByte()) buffer[ptr++] else -1

  operator fun hasNext(): Boolean {
    while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++
    return hasNextByte()
  }

  operator fun next(): String {
    if (!hasNext()) throw NoSuchElementException()
    val sb = StringBuilder()
    var b = readByte()
    while (isPrintableChar(b)) {
      sb.appendCodePoint(b.toInt())
      b = readByte()
    }
    return sb.toString()
  }

  fun nextChar(): Char {
    if (!hasNext()) throw NoSuchElementException()
    return readByte().toChar()
  }



  fun nextLong(): Long {
    if (!hasNext()) throw NoSuchElementException()
    var n = 0L
    try {
      var b = readByte()
      if (b == '-'.toByte()) {
        do {
          n = n * 10 + '0'.toLong() - b
          b = readByte()
        } while (isNumber(b))
        return n
      } else if (!isNumber(b)) throw NumberFormatException()
      do {
        n = n * 10 + b - '0'.toLong()
        b = readByte()
      } while (isNumber(b))
    } catch (e: NoSuchElementException) {
    }
    return n
  }

  fun nextInt(): Int {
    if (!hasNext()) throw NoSuchElementException()
    var n = 0
    try {
      var b = readByte()
      if (b == '-'.toByte()) {
        b = readByte()
        do {
          n = n * 10 + '0'.toInt() - b
          b = readByte()
        } while (isNumber(b))
        return n
      } else if (!isNumber(b)) throw NumberFormatException()
      do {
        n = n * 10 + b - '0'.toInt()
        b = readByte()
      } while (isNumber(b))
    } catch (e: NoSuchElementException) {
    }
    return n
  }

  fun nextDouble() = next().toDouble()

  private fun isPrintableChar(c: Byte) = 32 < c || c < 0

  private fun isNumber(c: Byte) = c.toChar() in ('0'..'9')
}

