#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
typedef pair<int, ll> E;
const ll inf = 1e18;

int n;
int d[300005];
vector<E> G[300005];
ll dp[300005][2];

void dfs(int v, int p)
{
  vector<ll> vec;
  for(auto e : G[v]){
    int u = e.first, w = e.second;
    if(u == p) continue;
    dfs(u, v);
    vec.push_back(dp[u][0]+w-dp[u][1]);
    dp[v][0] += dp[u][1], dp[v][1] += dp[u][1];
  }
  sort(vec.rbegin(), vec.rend());

  for(int i = 0; i < (int)vec.size(); i++){
    if(vec[i] <= 0) break;
    if(i < d[v]-1) dp[v][0] += vec[i];
    if(i < d[v]) dp[v][1] += vec[i];
  }
  if(d[v] == 0) dp[v][0] = -inf;
}

int main(void)
{
  cin >> n;
  for(int i = 1; i <= n; i++) cin >> d[i];
  int u, v, w;
  for(int i = 1; i <= n-1; i++){
    cin >> u >> v >> w;
    G[u].push_back(E(v, w));
    G[v].push_back(E(u, w));
  }
  dfs(1, -1);
  cout << dp[1][1] << endl;

  return 0;
}

