#include <iostream>
#include <vector>
using namespace std;

int main() {
  int N, M;
  cin >> N >> M;
  vector<int> A(N), B(N);
  for (int i = 0; i < N; i++) cin >> A[i] >> B[i];
  vector<vector<int>> inv(M + 1);
  for (int i = 0; i < N; i++) {
    inv[A[i]].push_back(i);
    inv[B[i]].push_back(i);
  }
  vector<int> cnt(N), ans(M + 3);
  int cnt_zero = N;
  for (int i = 1, j = 1; i <= M;) {
    while (j <= M and cnt_zero != 0) {
      for (auto& x : inv[j]) {
        if (cnt[x] == 0) cnt_zero--;
        cnt[x]++;
      }
      j++;
    }
    if (cnt_zero != 0) break;
    ans[j - i]++, ans[M + 1 - i + 1]--;
    for (auto& x : inv[i]) {
      cnt[x]--;
      if (cnt[x] == 0) cnt_zero++;
    }
    i++;
  }
  for (int i = 1; i <= M; i++) {
    ans[i] += ans[i - 1];
    cout << ans[i] << " \n"[i == M];
  }
}

use proconio::{input, marker::Usize1};
fn main() {
    input!(n: usize, m: usize, ab: [(Usize1, Usize1); n]);
    let mut l = vec![0; m];
    for &(a, b) in &ab {
        if a > 0 {
            l[0] = l[0].max(a);
        }
        if a + 1 < b {
            l[a + 1] = l[a + 1].max(b - a - 1);
        }
        if b + 1 < m {
            l[b + 1] = l[b + 1].max(m - b - 1);
        }
    }
    // l を L にする
    for i in 1..m {
        l[i] = (l[i] + 1).max(l[i - 1]) - 1;
    }
    let mut g = vec![0; m];
    for &k in &l {
        if k > 0 {
            g[k - 1] += 1;
        }
    }
    for k in (1..m).rev() {
        g[k - 1] += g[k];
    }
    let f = g
        .iter()
        .enumerate()
        .map(|(i, &g)| m - i - g)
        .map(|f| f.to_string())
        .collect::<Vec<_>>()
        .join(" ");
    println!("{}", f);
}

