#include <bits/stdc++.h>
#include <atcoder/all>
using namespace std;
using namespace atcoder;

int main() {
	int n, x, sz;
	int c[300000];
	vector<int>a[300001];
	long long ans = 0;

	cin >> n;
	for (int i = 0; i < n; i++)cin >> c[i];
	for (int i = 0; i < n; i++) {
		cin >> x;
		a[0].push_back(x - 1);
		a[c[i]].push_back(x - 1);
	}

	fenwick_tree<long long> fw(n);
	for (int i = 0; i <= n; i++) {
		sz = a[i].size();
		for (int j = 0; j < sz; j++) {
			if (i == 0)ans += fw.sum(a[i][j] + 1, n);
			else ans -= fw.sum(a[i][j] + 1, n);
			fw.add(a[i][j], 1LL);
		}
		for (int j = 0; j < sz; j++)fw.add(a[i][j], -1LL);
	}

	cout << ans << endl;
	return 0;
}

