struct linked_list {
  struct node {
    int val;
    node* next;
    node(int val, node* next) : val(val), next(next) {}
  };

  node* head;

  linked_list() : head(nullptr) {}

  void push(int val) { head = new node(val, head); }

  void pop() {
    if (head) {
      head = head->next;
    }
  }

  int get() {
    if (head) {
      return head->val;
    } else {
      return -1;
    }
  }
};

int main() {
  int q;
