int main() {
    using namespace std;

    unsigned N;
    cin >> N;

    // 列を base からの差分で管理
    vector<unsigned long> A(N);
    unsigned base{};

    for (auto &&a : A)cin >> a;
    A.emplace(begin(A));

    // 差分が 0 でないかもしれない場所
    // はじめは 1, ..., N すべて
    vector<unsigned> added_index(N);
    iota(begin(added_index), end(added_index), 1U);

    unsigned Q;
    cin >> Q;

    for (unsigned _{}; _ < Q; ++_) {
        unsigned type;
        cin >> type;
        if (type == 1) {
            // 差分が 0 でないところを消去
            while (!empty(added_index)) {
                A[added_index.back()] = 0;
                added_index.pop_back();
            }
            cin >> base;
        } else if (type == 2) {
            // index 番目の差分に加える
            unsigned index, value;
            cin >> index >> value;
            A[index] += value;
            added_index.emplace_back(index);
        } else {
            // base に index 番目の差分を加える
            unsigned index;
            cin >> index;
            cout << base + A[index] << endl;
        }
    }

    return 0;
}

