  mint sing=c;

  for(int i=2;i<=n;i++){
    if(i-k>=0){ sing+=dp[i-k]; }

    dp[i-1]=(sing*(c-1));
    dp[i-1]+=dp_sum[i-2];
    if(i-k>=0){ dp[i-1]-=dp_sum[i-k]; }

    dp_sum[i-1]=dp_sum[i-2]+dp[i-1];
  }

  mint res=sing;
  for(int i=n-k+1;i<=n;i++){res+=dp[i];}
  cout << res.val() << "\n";
  return 0;
}

