k = int(input())

# 素因数分解
pes = list()  # 素因数 p と 指数 e の組を格納
k2 = k
p = 2
while p * p <= k:
  e = 0
  while k2 % p == 0:
    k2 //= p
    e += 1
  if e > 0:
    pes.append((p, e))
  p += 1
if k2 > 1:
  pes.append((k2, 1))

# n! は p で何回割り切れるか（ルジャンドルの定理）
def legendre(n, p):
  res = 0
  p2 = p
  while True:
    tmp = n // p2
    if tmp == 0:
      break
    res += tmp
    p2 *= p
  return res

# 判定問題
def isok(n):
  for p, e in pes:
    if legendre(n, p) < e:
      return False
  return True

# 二分探索
ng, ok = 1, k  # k ≥ 2 なので 1! は k の倍数にならない、また k! は必ず k の倍数
while abs(ok - ng) > 1:
  mid = (ok + ng) // 2
  if isok(mid):
    ok = mid
  else:
    ng = mid
print(ok)

