template <class T>
struct matrix {
    int h, w;
    vector<vector<T>> e;
    matrix(int h_, int w_) : h(h_), w(w_), e(h_, vector<T>(w_)) {}
    std::vector<T> &operator[](int p) {
        return e[p];
    }
    const std::vector<T> &operator[](int p) const {
        return e[p];
    }
    matrix operator*(const matrix &m) {
        assert(w == m.h);
        matrix ret(h, m.w);
        for(int i = 0; i < h; i++) {
            for(int j = 0; j < m.w; j++) {
                for(int k = 0; k < w; k++) {
                    ret[i][j] += e[i][k] * m[k][j];
                }
            }
        }
        return ret;
    }
    matrix operator^(long long p) const {
        assert(h == w);
        matrix I(h, w), b(*this);
        for(int i = 0; i < h; i++) I[i][i] = T(1);
        while(p) {
            if(p & 1) I = I * b;
            b = b * b;
            p >>= 1;
        }
        return I;
    }
};

