long long greedy(long long x,long long k,long long p,vector<long long> &a){
  if(x==0){return 0;}
  if(x<0){return 8e18;}
  long long res=0;
  for(long long i=p;i>=0;i--){
    long long use=(x/a[i]);
    res+=use;
    x-=use*a[i];
  }
  if(x>0){return 8e18;}
  return res;
}

int main(){
  int tc;
  cin >> tc;
  while(tc>0){
    tc--;
    long long d,k,x;
