    for (unsigned i{}; i < N + M + 1; ++i) {
        C[i].first = C[i + 1].first - C[i].first;
        C[i + 1].second ^= C[i].second;
    }
    C.pop_back();

    unsigned long ans{};
    for (const auto&[l, c] : C)
        if (c == 0)
            ans += l;

    cout << ans << endl;

    return 0;
}

