int main() {
    using namespace std;
    unsigned N;
    cin >> N;
    string S;
    cin >> S;

    unsigned ans{};

    for (unsigned flip{}; flip < 2; ++flip) {
        // 極大な右ダンゴ文字列のレベルを列挙する
        unsigned level{};
        for (unsigned i{}; i < N; ++i)
            if (S[i] == '-') {
                // '-' に対応する極大な右ダンゴ列のレベルは、直前までの 'o' の個数
