	int n;
	cin >> n;
	vector<int> a(2 * n);
	for (int i = 0; i < 2 * n; i++) cin >> a[i];
	sort(a.begin(), a.end());
	a.push_back(7 << 28);
	int ans = 0;
	for (int i = 0; i < 30; i++) {
		int f = 0;
		int z = 1 << (i + 1);
		int nxt = a[0] / z * z + z / 2;
		int mx = a[0] / z * z + z;
		int tmp = -1;
		for (int j = 0; j < 2 * n + 1; j++) {
			if (a[j] >= nxt && tmp == -1) tmp = j;
			if (a[j] >= mx) {
				for (int k = f; k < j; k++) v[i][k] = tmp;
				f = j;
				nxt = a[j] / z * z + z / 2;
				mx = a[j] / z * z + z / 2;
				tmp = -1;
			}
			if (a[j] >= nxt && tmp == -1) tmp = j;
		}
	}
	for (int b = 29; b >= 0; b--) {
		int tmp = ans | (1 << b);
		int cnt = f(a, 0, 2 * n, tmp, 29);
