using pi=pair<int,int>;

#define mod 998244353

int main(){
  int n,m;
  cin >> n >> m;
  vector<pi> eg(m);
  for(auto &nx : eg){
    cin >> nx.first >> nx.second;
    nx.first--;nx.second--;
  }

  vector<int> comp(1<<n);
  for(int i=0;i<(1<<n);i++){
    int res=__builtin_popcount(i);
    dsu uf(n);
    for(auto &nx : eg){
      if((i&(1<<nx.first))==0){continue;}
      if((i&(1<<nx.second))==0){continue;}
      if(!uf.same(nx.first,nx.second)){
        uf.merge(nx.first,nx.second);
        res--;
      }
    }
    comp[i]=res;
  }

  vector<int> dp(1<<n,0);
  dp[0]=1;
  for(int i=1;i<(1<<n);i++){
    for(int j=(1<<n)-1;;j--){
      j&=i;
      if(j==0){break;}
      if(comp[j]%2){
        dp[i]+=dp[i^j];
      }
      else{
        dp[i]+=(mod-dp[i^j]);
      }
      dp[i]%=mod;
    }
  }
  cout << dp[(1<<n)-1] << "\n";
  return 0;
}

