using namespace std;

int get(vector<vector<int>> E,int s){
	int n = E.size();
	vector<int> dist(n,-1);

	dist[s] = 0;
	queue<int> Q;
	Q.push(s);

	while(Q.size()>0){
		int x = Q.front();
		Q.pop();
		for(int i=0;i<E[x].size();i++){
			int y = E[x][i];
			if(dist[y]==-1){
				dist[y] = dist[x]+1;
				Q.push(y);
			}
		}
	}

	return *max_element(dist.begin(),dist.end());
}

