bool judge(long long k){
  int le=-1,ri=0,nx;
  for(int i=0;i<n;i++){
    if(x[i]<k)le++,ri++;
    else break;
  }
  for(int i=0;i<n;i++){
    if(le<0)nx=ri,ri++;
    else if(ri>=n)nx=le,le--;
    else if((k-x[le])>(x[ri]-k))nx=ri,ri++;
    else nx=le,le--;
    if(abs(x[nx]-k)>l[i])return false;
  }
  return true;
}


