    int n, m, p;
    cin >> n >> m >> p;
    vector<int> a(n), b(m);
    for (int &i: a) cin >> i;
    for (int &i: b) cin >> i;
    sort(b.begin(), b.end());
    vector<ll> b_sum(m + 1);
    for (int i = 0; i < m; i++) {
        b_sum[i + 1] = b_sum[i] + b[i];
    }
    ll ans = 0;
    for (int i: a) {
        int lb = lower_bound(b.begin(), b.end(), p - i) - b.begin();
        ans += (ll) i * lb;
        ans += b_sum[lb];
        ans += (ll) p * (m - lb);
    }
    cout << ans << endl;
}

