        pow_3.emplace_back(pow_3[i] * pow_3[i]); // 3^(2^i)^2 = 3^(2^(i+1)) を計算

    while (!empty(pow_3)) {
        if (N % pow_3.back() == 0) // 3^(2^i) で割れたら割る
            N /= pow_3.back();
        pow_3.pop_back();
    }

    if (has_single_bit(N)) // 残りが 2 の累乗なら Yes
        cout << "Yes" << endl;
    else
        cout << "No" << endl;

    return 0;
}

