        }
        for(int i = 0; i < m; i ++) {
            a[i] += wc;
            dfs(dfs, a, cnt, sum2 + a[i] * wc * 2 - wc2);
            a[i] -= wc;
        }
    };
    vector<ll> base(1, w[0]); 
    dfs(dfs, base, 1, w[0] * w[0]);
    cout << fixed << setprecision(10) << (double)(ans * d - sum1 * sum1) / (double)(d * d) <<endl;
