using ll = long long;
#include <atcoder/internal_math>
using namespace atcoder;

// f(n, s, r, m) := n 以下で、桁和が s で、m で割って r あまるものの個数
map<ll, ll> mem[130][130][130];  // mem[s][r][m][n] にメモ
ll f(ll n, int s, int r, int m)
{
  if (n == 0)
    return s == 0 && r == 0;
  if (mem[s][r][m].contains(n))
    return mem[s][r][m][n];
  ll res = 0;
  for (int d = 0; d < 10; d++)
  {
    ll nn = n / 10 - (d > n % 10);
    int ns = s - d;
    if (nn < 0 || ns < 0)
      continue;
    auto [g, x] = internal::inv_gcd(10, m);
    if ((r - d) % g != 0)
      continue;
    int nm = m / g;
    int nr = (((r - d) / g * x) % nm + nm) % nm;
    res += f(nn, ns, nr, nm);
  }
  mem[s][r][m][n] = res;
  return res;
}

int main()
{
  ll N;
  cin >> N;
  ll ans = 0;
  for (int s = 1; s <= 126; s++)
  {
    ans += f(N, s, 0, s);
  }
  cout << ans << endl;
}

