#include <iostream>
#include <atcoder/fenwicktree>

int main() {
    using namespace std;
    unsigned N, M;
    cin >> N >> M;

    atcoder::fenwick_tree<unsigned long> D(N);
    { // BIT を初期化
        unsigned long A, prev_A{};
        for(unsigned i = 0; i < N; ++i){
            cin >> A;
            // ∑_j D[j] = A[i] とするには D[i] = A[i] - A[i - 1] とすればよい
            D.add(i, A - prev_A);
            prev_A = A;
        }
    }

    for(unsigned i = 0; i < M; ++i){
        unsigned B;
        cin >> B;
        auto x{D.sum(0, B + 1)}; // A[B] の値は ∑_{0 <= j <= B} D[j]

        // A[B] の値を 0 にする
        D.add(B, -x);
        if(B + 1 < N)D.add(B + 1, x);

        // 全体には足さないぶんの処理
        D.add((B + 1) % N, 1); // 配り始めから末尾まで +1
        D.add((B + 1 + x) % N, -1); // 配り終わりから末尾まで -1
        x += (B + 1) % N - (B + 1 + x) % N; // 足したぶんを引いておく

        // 全体に x / N を足す
        D.add(0, x / N);
    }

    for(unsigned i = 1; i <= N; ++i)
        cout << D.sum(0, i) << " ";
    cout << endl;

    return 0;
}

// 拡張ユークリッドの互除法の実装例
pair<long long, long long> extgcd(long long a, long long b) {
  if (b == 0) return make_pair(1, 0);
  long long x, y;
  tie(y, x) = extgcd(b, a % b);
  y -= a / b * x;
  return make_pair(x, y);
}

