#include <iostream>
#include <utility>
#include <optional>
#include <vector>
#include <queue>
#include <limits>
#include <ranges>

int main() {
    using namespace std;
    unsigned N, M;
    cin >> N >> M;

    // 電車の情報を保持する構造体
    struct train {
        unsigned from, to;
        unsigned long first_train;
        unsigned long interval;
        unsigned long count;
        unsigned long distance;

        // time_limit までに駅 to へ到着するような列車の出発時刻のうち最小のものを求める
        // 存在しなければ nullopt を返す
        optional<unsigned long> get_last_train(unsigned long time_limit) const {
            if (time_limit < first_train + distance)
                return nullopt;
            return first_train + min(count - 1, (time_limit - first_train - distance) / interval) * interval;
        }
    };
    vector<vector<train>> train_info(N);
    for (const auto _ : views::iota(0U, M)) {
        unsigned long l, d, k, c;
        unsigned A, B;
        cin >> l >> d >> k >> c >> A >> B;
        train_info[--B].push_back({--A, --B, l, d, k, c});
    }

    priority_queue<pair<unsigned long, unsigned>> pq;
    vector<unsigned long> ans(N);

    // 駅 N に十分遅い時間にいるところから探索を始める
    pq.emplace(ans.back() = numeric_limits<unsigned long>::max(), N - 1);
    while (!empty(pq)) {
        // まだ探索していない駅のうちもっとも遅くまでいられる駅を探索する
        const auto[time_limit, now]{pq.top()};
        pq.pop();
        if (ans[now] > time_limit)continue;

        // 駅 now に向かう電車情報に対して
        for (const auto &e : train_info[now]) {
            const auto next{e.from};
            const auto next_time{e.get_last_train(time_limit)};
            // 駅 next の最終時刻 ≥ 駅 now の最終時刻に間に合う電車の発射時刻
            if (next_time && ans[next] < *next_time) // 更新できるなら
                pq.emplace(ans[next] = *next_time, next); // 優先度つきキューに入れる
        }
    }

    for (const auto d : ans | views::take(N - 1))
        if (d)
            cout << d << endl;
        else
            cout << "Unreachable" << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <utility>
#include <tuple>

int main() {
    using namespace std;

    // 消せる priority_queue に対する操作
    using erasable_priority_queue = pair<priority_queue<unsigned>, priority_queue<unsigned>>;
    // x を追加する関数
    const auto add{[](unsigned x) { return [x](auto &&pq) { return pq.first.push(x); }; }};
    // x を削除する関数
    const auto erase{[](unsigned x) { return [x](auto &&pq) { return pq.second.push(x); }; }};
    // pq に含まれる値の max (空なら 0 ) を返す関数
    const auto top_or_zero{[](auto &&pq) {
        while (!empty(pq.second) && pq.first.top() == pq.second.top()) {
            pq.first.pop();
            pq.second.pop();
        }
        return empty(pq.first) ? 0 : pq.first.top();
    }};

    unsigned N;
    cin >> N;

    vector<erasable_priority_queue> intervals(2 * N);
    for (unsigned i{}, a; i < N; ++i) {
        cin >> a;
        add(a)(intervals[i + N]); // [i, i+1) に対応する区間に a を追加
    }

    // [l, r) を O(log N) 個の区間に分割し、各区間 I に対して callback(I) を呼び出す
    const auto range_update{[N, &intervals](unsigned l, unsigned r, const auto &callback) {
        l += N;
        r += N;
        while (l != r) {
            if (l & 1)
                callback(intervals[l++]);
            if (r & 1)
                callback(intervals[--r]);
            l /= 2;
            r /= 2;
        }
    }};

    // i を含む O(log N) 個の区間を列挙し、各区間 I について mapping(I) を呼び出した結果 m を aggregate(ret, m) で集計する
    const auto point_access{[N, &intervals](unsigned i, const auto &mapping, const auto &aggregate) {
        i += N;
        unsigned ret{};
        while (i) {
            ret = aggregate(ret, mapping(intervals[i]));
            i /= 2;
        }
        return ret;
    }};

    unsigned Q;
    cin >> Q;
    vector<tuple<unsigned, unsigned, unsigned>> instructions(Q);
    for (auto&&[l, r, x] : instructions) {
        unsigned type;
        cin >> type;
        if (type == 1) {
            cin >> l >> r >> x;
            --l;
            range_update(l, r, add(x)); // [l, r) に x を追加
        } else if (type == 2) {
            cin >> x;
            const auto&[l_erased, r_erased, x_erased]{instructions[x - 1]};
            range_update(l_erased, r_erased, erase(x_erased)); // [l_erased, r_erased) から x_erased を削除
        } else {
            cin >> x;
            // 最大値を出力
            cout << point_access(x - 1, top_or_zero, [](auto a, auto b) { return max(a, b); }) << endl;
        }
    }
    return 0;
}

