#include <iostream>
#include <vector>
#include <ranges>
#include <utility>
#include <optional>

int main() {
    using namespace std;
    using bigint = __int128;

    constexpr bigint inf = bigint{1} << 100;

    unsigned N;
    cin >> N;

    vector P(N, vector<unsigned>(N)), R(N, vector<unsigned>(N)), D(N, vector<unsigned>(N));

    for (auto &&v : P)
        for (auto &&p : v)
            cin >> p;
    for (auto &&v : R)
        for (auto &&r : v | views::take(N - 1))
            cin >> r;
    for (auto &&v : D | views::take(N - 1))
        for (auto &&d : v)
            cin >> d;

    vector<vector<pair<bigint, bigint>>> dp(N + 1);
    dp[N - 1].emplace_back(0, 0);

    // p1, p2, p3 の 3 点ともに凸包に必要なら true を返す
    const auto check{[](const auto &p1, const auto &p2, const auto &p3) {
        const auto&[a, b]{p1};
        const auto&[c, d]{p2};
        const auto&[e, f]{p3};
        return a * d + c * f + e * b < a * f + c * b + e * d;
    }};

    // 点列 convex_hull (型は vector<pair>) のそれぞれの点を +(cost, 1) だけした列を作る
    // 呼び出すたびに点を先頭から返す関数オブジェクトを返す
    const auto shift_yield{[](const vector<pair<bigint, bigint>>& convex_hull, unsigned cost){
        return [&convex_hull, cost, it{begin(convex_hull)}]() mutable -> optional<pair<bigint, bigint>> {
            if (it == end(convex_hull))
                return nullopt;
            auto [money, turn]{*it};
            ++it;
            return make_pair(money + cost, turn + 1);
        };
    }};
    // ソートされた点列を 2 つとり、マージした点列を作る
    // 呼び出すたびに点を先頭から返す関数オブジェクトで点列を表す
    const auto merge_seqs{[](auto&& seq1, auto&& seq2){
        return [&seq1, &seq2, front1{seq1()}, front2{seq2()}]() mutable -> optional<pair<bigint, bigint>> {
            if(!front1 || (front2 && front1->first < front2->first))
                return exchange(front2, seq2());
            return exchange(front1, seq1());
        };
    }};

    for(unsigned i{N}; i--; ){
        for(unsigned j{N}; j--; ){
            vector<pair<bigint, bigint>> bottom;
            swap(bottom, dp[j]); // 旧 dp[j] を bottom とし、更新を行う

            const auto p{P[i][j]};

            // このマスでの最適な行動を持っておく
            bigint earn_here{inf};
            unsigned earn_index{};

            // 点列を作る
            optional<pair<bigint, bigint>> now;
            auto D_seq{shift_yield(bottom, D[i][j])}; // 下のマスへ移動するときの凸包
            auto R_seq{shift_yield(dp[j + 1], R[i][j])}; // 右のマスへ移動するときの凸包
            auto candidate_points{merge_seqs(D_seq, R_seq)}; // マージした列

            while (now = candidate_points()) { // マージした列から点を取り出して
                // 凸包を作る
                while (size(dp[j]) > 1 && !check(dp[j][size(dp[j]) - 2], dp[j].back(), *now))
                    dp[j].pop_back();
                dp[j].emplace_back(*now);

                // 0 から稼ぐときの最適を更新
                if (earn_here > now->first + now->second * p) {
                    earn_here = now->first + now->second * p;
                    earn_index = size(dp[j]);
                }
            }
            // 0 から稼いだほうがいい部分を消す
            dp[j].erase(begin(dp[j]) + earn_index, end(dp[j]));

            // 端数と 0 の点を追加
            if (dp[j].back().first > 1 && earn_here % p) dp[j].emplace_back(earn_here % p, earn_here / p);
            if (dp[j].back().first) dp[j].emplace_back(0, (earn_here + p - 1) / p);
        }
    }

    cout << static_cast<unsigned long>(dp.front().back().second) - 1 << endl;
    return 0;
}

#include<bits/stdc++.h>

using namespace std;
using pl=pair<long long,long long>;
using ppl=pair<pl,long long>;

long long g;
long long md=((1ll<<31)-1);
long long gen(){
  g = (48271*g) % md;
  return g;
}

long long comp_pl(pl a,pl b){
  long long l=a.first*b.second;
  long long r=a.second*b.first;
  if(l<r){return -1;}
  if(l>r){return 1;}
  return 0;
}

int main(){
  long long n;
  cin >> n;
  vector<pl> p(n);
  for(long long i=0;i<n;i++){
    cin >> p[i].first >> p[i].second;
  }
  sort(p.begin(),p.end());

  priority_queue<ppl,vector<ppl>,decltype(
    [](ppl a,ppl b){
      long long cp=comp_pl(a.first,b.first);
      if(cp==0){return (a.second>b.second);}
      if(cp==-1){return false;}
      return true;
    }
  )> pq;

  for(long long i=1;i<n;i++){
    if(p[i-1].first<p[i].first){
      ppl x;
      x.first={p[i].second-p[i-1].second,p[i].first-p[i-1].first};
      x.second=i;
      pq.push(x);
    }
  }

  long long q,ra,rb;
  cin >> q >> g >> ra >> rb;

  vector<pl> ask;
  for(long long i=0;i<q;i++){
    long long g1=gen();
    long long g2=gen();
    long long g3=gen();

    long long a = -ra + (g1%(2*ra+1));
    long long b = -rb + ((g2*md+g3)%(2*rb+1));
    ask.push_back({a,b});
  }

  sort(ask.begin(),ask.end());

  long long res=0;
  for(long long ak=0;ak<q;ak++){
    long long a=ask[ak].first;
    long long b=ask[ak].second;
    while(!pq.empty()){
      ppl od=pq.top();
      long long i=od.second;
      if(
        od.first!=make_pair(p[i].second-p[i-1].second,p[i].first-p[i-1].first)
      ){pq.pop();continue;}

      pl cp=od.first;
      pl cd={a,1};
      if(comp_pl(cp,cd)!=-1){break;}

      pq.pop();
      swap(p[i-1],p[i]);
      i--;
      if(i>0 && p[i-1].first<p[i].first){
        ppl x;
        x.first={p[i].second-p[i-1].second,p[i].first-p[i-1].first};
        x.second=i;
        pq.push(x);
      }
      i+=2;
      if(i<n && p[i-1].first<p[i].first){
        ppl x;
        x.first={p[i].second-p[i-1].second,p[i].first-p[i-1].first};
        x.second=i;
        pq.push(x);
      }
    }

    long long l=0,r=n-1;
    while(l<=r){
      long long te=(l+r)/2;
      if(p[te].second >= a*p[te].first+b){r=te-1;}
      else{l=te+1;}
    }

    res+=(n-1-r);
  }

  cout << res << "\n";
  return 0;
}

