    if((a + b + c) % 2 != 0 || a + b + c > 120 || a > b + c || b > c + a || c > a + b){
        cout << "-1" << endl;
        return 0;
    }

    // n?? = X, Y の k 桁目が ?? であるような k の個数
    unsigned n00{60 - (a + b + c) / 2}, n01{(-a + b + c) / 2}, n10{(a - b + c) / 2}, n11{(a + b - c) / 2};

    unsigned long X{}, Y{};
    for(unsigned B = 60; B--;){ // 上の bit から見る
        // 1 bit ずつ上に持ち上げて
        X *= 2;
        Y *= 2;

        if(1 & (C >> B)){ // C の B bit 目が 1 なら
            if(n10){ // (1, 0) が余っていれば
                ++X; // X の B bit 目を 1, Y の b bit 目を 0 に
                --n10; // 在庫を減らす
            }else{ // 余っていなければ
                ++Y; // Y のほうを 1 に
                --n01; // 在庫を減らしておく
            }
        }else{ // B bit 目が 0 なら
            if(n00){ // (0, 0) が余っていれば
                --n00; // どちらも 0 にし、在庫を減らす
            }else{ // 余っていなければ
                ++X; // どちらも 1 にし、
                ++Y;
                --n11; // 在庫を減らす
            }
        }
    }

    cout << X << " " << Y << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <ranges>
#include <numeric>
#include <algorithm>

int main() {
    using namespace std;
    static constexpr auto chmax{[](auto &&x, const auto &y) {
        if (x < y) x = y;
        return x;
    }};
    static constexpr auto max{[](const auto &x, const auto &y) {
        if (x < y) return y;
        return x;
    }};

    unsigned N, M;
    cin >> N >> M;

    // sum[i][j] := (i, j) を左上とする M × M 正方形内部の合計
    auto sum{[N, M] {
        vector A(N + 1, vector<unsigned long>(N + 1));
        for (auto &&row: A | views::take(N))
            for (auto &&a: row | views::take(N))
                cin >> a;

        // A[i][j] ← ∑_{i≤k,j≤l} A[k][l] とする
        for (unsigned row_index{N}; auto &&row : A | views::reverse){
        inclusive_scan(rbegin(row), rend(row), rbegin(row), plus<>{});
        if (row_index < N)
            ranges::transform(row, A[row_index + 1], begin(row), plus<>{});
        --row_index;
    }

        // sum[i][j] = A[i][j] - A[i+M][j] - A[i][j+M] + A[i+M][j+M]
        vector sum(N - M + 1, vector<unsigned long>(N - M + 1));
        for (unsigned i{}; i <= N - M; ++i)
            for (unsigned j{}; j <= N - M; ++j)
                sum[i][j] = A[i][j] - A[i + M][j] - A[i][j + M] + A[i + M][j + M];
        return sum;
    }()};

    // sum[i][j] の左上からの累積 max
    // m[i][j] = max_{k≤i,l≤j} sum[k][l]
    const auto max_UL{[](auto cells) {
        for (unsigned row_index{}; auto &&row : cells){
        inclusive_scan(begin(row), end(row), begin(row), max);
        if (row_index)
            ranges::transform(row, cells[row_index - 1], begin(row), max);
        ++row_index;
    }
        return cells;
    }};

    // 盤面を左右反転する
    const auto h_flip{[](auto &&cells) {
        for (auto &&row: cells)
            ranges::reverse(row);
        return cells;
    }};
    // 盤面を上下反転する
    const auto v_flip{[](auto &&cells) {
        ranges::reverse(cells);
        return cells;
    }};

    const auto upper_left{max_UL(sum)}; // 左上からの累積 max
    h_flip(sum); // 左右反転
    const auto upper_right{h_flip(max_UL(sum))}; // 右上からの累積 max
    v_flip(sum); // 上下反転
    const auto lower_right{h_flip(v_flip(max_UL(sum)))}; // 右下からの累積 max
    h_flip(sum); // 左右反転
    const auto lower_left{v_flip(max_UL(sum))}; // 左下からの累積 max
    v_flip(sum); // 元に戻す

    unsigned long ans{};

    // 正方形を 1 つ固定
    for (unsigned i{}; i < N - M + 1; ++i)
        for (unsigned j{}; j < N - M + 1; ++j) {
            if (M <= i && i + M < N - M + 1) // 上下に 3 つ並ぶ 中央固定
                chmax(ans, upper_left[i - M].back() + sum[i][j] + lower_right[i + M].front());
            if (M <= j && j + M < N - M + 1) // 左右に 3 つ並ぶ 中央固定
                chmax(ans, upper_left.back()[j - M] + sum[i][j] + lower_right.front()[j + M]);
            if (M <= i) { // T 型
                if (j + M < N - M + 1) // 左下
                    chmax(ans, upper_left[i - M].back() + lower_right[i][j + M] + sum[i][j]);
                if (M <= j) // 右下
                    chmax(ans, upper_left[i - M].back() + lower_left[i][j - M] + sum[i][j]);
            }
            if (M <= j) { // ト型
                if (i + M < N - M + 1) // 右下
                    chmax(ans, lower_left.front()[j - M] + lower_right[i + M][j] + sum[i][j]);
                if (M <= i) // 右上
                    chmax(ans, lower_left.front()[j - M] + upper_right[i - M][j] + sum[i][j]);
            }
            if (i + M < N - M + 1) { // 亠 型
                if (j + M < N - M + 1) // 左上
                    chmax(ans, lower_right[i + M].front() + upper_right[i][j + M] + sum[i][j]);
                if (M <= j) // 右上
                    chmax(ans, lower_right[i + M].front() + upper_left[i][j - M] + sum[i][j]);

            }
            if (j + M < N - M + 1) { // ㅓ 型
                if (i + M < N - M + 1) // 左上
                    chmax(ans, upper_right.back()[j + M] + lower_left[i + M][j] + sum[i][j]);
                if (M <= i) // 左下
                    chmax(ans, upper_right.back()[j + M] + upper_left[i - M][j] + sum[i][j]);
            }
        }

    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <atcoder/maxflow>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;

    atcoder::mf_graph<int> G(1 + 4 * N * N + 1);
    // S-T カットに帰着
    const unsigned S = 0, T = 1 + 4 * N * N;
    // 条件「マス (i, j) の値が v より大きい」に対応する頂点番号を返す関数
    const auto index{[N](unsigned i, unsigned j, unsigned v){ return (i * N + j) * 4 + v; }};

    constexpr int inf = 2 * 20 * 19 * 16 + 1; // ありえるコストの最大値より大きい値を inf とする

    for(unsigned i{}; i < N; ++i)
        for(unsigned j{}; j < N; ++j)
            for(unsigned v{1}; v + 1 <= 4; ++v)
                // (i,j) が v+1 より大 ⟹ v より大 : v+1 が 1 かつ v が 0 ならペナルティ +∞
                G.add_edge(index(i, j, v + 1), index(i, j, v), inf);

    // 横のマスの差の二乗
    for(unsigned i{}; i < N; ++i)
        for(unsigned j{}; j + 1 < N; ++j)
            for(unsigned v{1}; v <= 4; ++v){
                G.add_edge(index(i, j, v), index(i, j + 1, v), 1);
                G.add_edge(index(i, j + 1, v), index(i, j, v), 1);
                for(unsigned u{1}; u < v; ++u){
                    G.add_edge(index(i, j, v), index(i, j + 1, u), 2);
                    G.add_edge(index(i, j + 1, v), index(i, j, u), 2);
                }
            }

    // 縦のマスの差の二乗
    for(unsigned i{}; i + 1 < N; ++i)
        for(unsigned j{}; j < N; ++j)
            for(unsigned v{1}; v <= 4; ++v){
                G.add_edge(index(i, j, v), index(i + 1, j, v), 1);
                G.add_edge(index(i + 1, j, v), index(i, j, v), 1);
                for(unsigned u{1}; u < v; ++u){
                    G.add_edge(index(i, j, v), index(i + 1, j, u), 2);
                    G.add_edge(index(i + 1, j, v), index(i, j, u), 2);
                }
            }

    // すでに書き込まれているマス
    for(unsigned i{}; i < N; ++i)
        for(unsigned j{}; j < N; ++j){
            unsigned A;
            cin >> A;
            if(A == 0)
                continue;
            if(A < 5)
                G.add_edge(index(i, j, A), T, inf);
            if(A > 1)
                G.add_edge(S, index(i, j, A - 1), inf);
        }

    // S から T までフローを流し、最小カットを求める
    G.flow(S, T);
    const auto& cut{G.min_cut(S)};

    for(unsigned i{}; i < N; ++i){
        for(unsigned j{}; j < N; ++j){
            unsigned B{1};
            for(unsigned v{1}; v <= 4; ++v)
                B += cut[index(i, j, v)];
            cout << B << " ";
        }
        cout << endl;
    }

    return 0;
}

