    unsigned long Sx, Sy, Tx, Ty;
    cin >> Sx >> Sy >> Tx >> Ty;
    // K ずつ右上にずらしておく
    Sx += K;
    Sy += K;
    Tx += K;
    Ty += K;

    // 上界を入れておく
    unsigned long dist{max(Tx, Sx) - min(Tx, Sx) + max(Ty, Sy) - min(Ty, Sy)};

    // 1 < K のとき、大タイルを経由する移動を考える
    if(1 < K){
        vector<tuple<unsigned long, unsigned long, unsigned long>> large_start; // はじめに到達する大タイルの候補
        if(((Sx / K) ^ (Sy / K)) & 1) // 開始位置が大タイルなら
            large_start.emplace_back(Sx / K, Sy / K, 0); // その大タイル
        else{ // そうでなければ、四方向いずれかで最も近い大タイルが候補
            large_start.emplace_back(Sx / K - 1, Sy / K, 1 + Sx % K); // 左
            large_start.emplace_back(Sx / K + 1, Sy / K, K - Sx % K); // 右
            large_start.emplace_back(Sx / K, Sy / K - 1, 1 + Sy % K); // 下
            large_start.emplace_back(Sx / K, Sy / K + 1, K - Sy % K); // 上
        }

        vector<tuple<unsigned long, unsigned long, unsigned long>> large_goal; // 最後に到達する大タイルの候補
        if(((Tx / K) ^ (Ty / K)) & 1) // 終了位置が大タイルなら
            large_goal.emplace_back(Tx / K, Ty / K, 0); // その大タイル
        else{ // そうでなければ、四方向いずれかで最も近い大タイルが候補
            large_goal.emplace_back(Tx / K - 1, Ty / K, 1 + Tx % K); // 左
            large_goal.emplace_back(Tx / K + 1, Ty / K, K - Tx % K); // 右
            large_goal.emplace_back(Tx / K, Ty / K - 1, 1 + Ty % K); // 下
            large_goal.emplace_back(Tx / K, Ty / K + 1, K - Ty % K); // 上
        }

        // K = 2 かどうかで場合分け
        if(K == 2)
            for(const auto& [x, y, d1] : large_start)
                for(const auto& [z, w, d2] : large_goal){
                    const auto x_diff{max(x, z) - min(x, z)};
                    const auto y_diff{max(y, w) - min(y, w)};
                    dist = min(dist, d1 + d2 + x_diff + y_diff + (max(x_diff, y_diff) - min(x_diff, y_diff)) / 2);
                }
        else
            for(const auto& [x, y, d1] : large_start)
                for(const auto& [z, w, d2] : large_goal)
                    dist = min(dist, d1 + d2 + max(x + y, z + w) - min(x + y, z + w) + max(x + w, z + y) - min(x + w, z + y));
    }
    cout << dist << endl;
    return 0;
}

#include <iostream>
#include <atcoder/segtree>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;
    unsigned long C;
    cin >> C;
    unsigned M;
    cin >> M;

    // range max を求めるセグメント木
    using range_max = atcoder::segtree<unsigned long, [](auto a, auto b){return max(a, b);}, []{return 0UL;}>;

    // (i, dp[i] + Ci) の prefix max を管理するセグメント木と、
    // (i, dp[i] - Ci) の suffix max を管理するセグメント木
    range_max prefix(N), suffix(N);

    // 初期値をオーバーフローを起こさない程度の値に設定
    constexpr unsigned long offset{2000000000000000000};

    // dp[0] = offset に対応
    prefix.set(0, offset);
    suffix.set(0, offset);

    // これまでの所持金の最大値
    unsigned long ans{offset};

    for (unsigned i{}; i < M; ++i) {
        unsigned T;
        unsigned long P;
        cin >> T >> P;
        --T;

        // dp[i] + Ci のうち i が T 以下であるような最大のものと、
        // dp[i] - Ci のうち i が T 以上であるような最小のものをとる
        // 前者の値 - CT と後者の値 + CT の小さくないほうを求めて、更新に用いる
        const auto best{max(prefix.prod(0, T + 1) - C * T, suffix.prod(T, N) + C * T) + P};

        // 所持金の最大値を更新
        ans = max(ans, best);

        // 更新
        prefix.set(T, best + C * T);
        suffix.set(T, best - C * T);
    }

    // 初期値を引いた値が求める答え
    cout << ans - offset << endl;
    return 0;
}

#include <iostream>
#include <set>

int main() {
    using namespace std;
    unsigned N;
    unsigned long C;
    unsigned M;
    cin >> N >> C >> M;

    // (i, dp[i] + Ci) の prefix max を管理する set と、
    // (i, dp[i] - Ci) の suffix max を管理する set
    set<pair<unsigned, unsigned long>> prefix_max, suffix_max;

    // 初期値をオーバーフローを起こさない程度の値に設定
    constexpr unsigned long offset{2000000000000000000};

    // dp[0] = offset に対応
    prefix_max.emplace(0, offset);
    suffix_max.emplace(0, offset);

    // これまでの所持金の最大値
    unsigned long ans{offset};

    for (unsigned i{}; i < M; ++i) {
        unsigned T;
        unsigned long P;
        cin >> T >> P;
        --T;

        // (i, dp[i] + Ci) のうち i が T 以下であるような最大の i と、
        // (i, dp[i] - Ci) のうち i が T 以上であるような最小の i をとる
        // 前者の値 - CT と後者の値 + CT の小さくないほうを求めて、更新に用いる
        const auto best{max([C, T, &prefix_max]{
                                if(const auto it{prefix_max.lower_bound({T + 1, 0})}; it != begin(prefix_max))
                                    return prev(it)->second - C * T;
                                return 0UL;
                            }(), [C, T, &suffix_max]{
                                if(const auto it{suffix_max.lower_bound({T, 0})}; it != end(suffix_max))
                                    return it->second + C * T;
                                return 0UL;
                            }()) + P};

        // 所持金の最大値を更新
        ans = max(ans, best);

        // T 以降でより大きくないものを削除して、新しい値を追加
        auto prefix_upper{prefix_max.lower_bound({T, 0})};
        while (prefix_upper != end(prefix_max) && prefix_upper->second <= best + C * T)
            prefix_upper = prefix_max.erase(prefix_upper);
        prefix_max.emplace_hint(prefix_upper, T, best + C * T);

        // T 以前でより大きくないものを削除して、新しい値を追加
        auto suffix_lower{suffix_max.lower_bound({T + 1, 0})};
        while (suffix_lower != begin(suffix_max) && prev(suffix_lower)->second <= best - C * T)
            suffix_max.erase(prev(suffix_lower));
        suffix_max.emplace_hint(suffix_lower, T, best - C * T);
    }

    // 初期値を引いた値が求める答え
    cout << ans - offset << endl;
    return 0;
}

