            paper = 0;
            ++rock;
        } else if (c == 'P') {
            rock = 0;
            ++scissors;
        }
    }

    cout << ranges::max(dp) << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <atcoder/segtree>

int main() {
    using namespace std;
    // x の区間 [A, B] に入って出ていくときの動きとコストを表す構造
    // 入るときの y 座標の値を入れると (出るときの y 座標, 移動回数) を返す
    struct block{
        unsigned fL, fU;
        unsigned gL, gU;
        unsigned long C;
        pair<unsigned, unsigned long> operator()(unsigned y) const {
            return {clamp(y, fL, fU), C + max(y, gL) - min(y, gU)};
        }
    };
    // セグメント木の定義
    // 二項演算は区間の合併
    using segment_tree = atcoder::segtree<block, [](const block& lhs, const block& rhs) -> block {
        // 区間の合併はがんばる
        const auto new_fL{clamp(lhs.fL, rhs.fL, rhs.fU)}, new_fU{clamp(lhs.fU, rhs.fL, rhs.fU)};
        const auto new_gL{clamp(rhs.gL, lhs.gL, lhs.gU)}, new_gU{clamp(rhs.gU, lhs.gL, lhs.gU)};
        const auto new_C{lhs.C + rhs(lhs(new_gU).first).second};
        return {new_fL, new_fU, new_gL, new_gU, new_C};
    }, []{
        // 単位元は全面素通し
        return block{0, 1000000001, 0, 1000000001, 0};
    }>;

    unsigned N;
    cin >> N;
    vector<block> intervals(N);
    for(auto&& [fL, fU, gL, gU, C] : intervals){
        unsigned L, U;
        cin >> L >> U;
        // [L, U] が空いている列に対応する値を作る
        fL = gL = L;
        fU = gU = U;
        C = 1;
    }
    segment_tree seg_tree{intervals};

    unsigned Q;
    cin >> Q;
    for(unsigned i{}; i < Q; ++i){
        unsigned sx, sy, tx, ty;
        cin >> sx >> sy >> tx >> ty;
        if (sx > tx){
            swap(sx, tx);
            swap(sy, ty);
        }
        // [sx, tx] に sy から入ったときの (出てくる y 座標, 移動回数)
        const auto& [out, cost]{seg_tree.prod(sx, tx)(sy)};
        // 最後に y 座標を調節して出力
        cout << max(out, ty) - min(out, ty) + cost << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <utility>
#include <map>
#include <algorithm>

int main() {
    using namespace std;
    unsigned N, M;
    cin >> N >> M;
    vector<pair<unsigned, unsigned>> records(M);
    for (auto &&[T, P]: records) {
        cin >> T >> P;
        --P;
    }
    vector<vector<pair<unsigned, unsigned>>> inside_office(N);
    {
        vector<unsigned> in(N);
        for (const auto &[T, P]: records) {
            if (in[P]) {
                inside_office[P].emplace_back(in[P], T);
                in[P] = 0;
            } else
                in[P] = T;
        }
    }
    constexpr unsigned large_limit{1000};
    map<pair<unsigned, unsigned>, unsigned> memo;

    // 集合のサイズが大きいほうに対する答えを求める
    for (unsigned i{}; const auto &Si : inside_office) {
        if (size(Si) > large_limit) {
            vector<unsigned> sum(N);
            // i 番目の高橋くんがこれまで合計何分いたかを求める
            unsigned prev_i{}, i_sum{};
            bool i_inside{false};
            // 累積和で P 番目の高橋くんが i 番目の高橋くんと同時にいた時刻を求める
            for (const auto &[T, P]: records) {
                if (P == i) {
                    i_sum += i_inside * (T - prev_i);
                    prev_i = T;
                    i_inside ^= true;
                }
                sum[P] = i_sum + i_inside * (T - prev_i) - sum[P];
            }
            for (unsigned j{}; j < N; ++j)
                memo[minmax(i, j)] = sum[j];
        }
        ++i;
    }

    // 両方が小さい場合の答えを求める
    const auto query{[&inside_office, &memo](unsigned a, unsigned b) {
        if (memo.contains({a, b}))
            return memo[{a, b}];
        const auto &Sa{inside_office[a]};
        const auto &Sb{inside_office[b]};
        // どちらかが空なら、答えは 0
        if (empty(Sa) || empty(Sb))
            return memo[{a, b}] = 0;
        unsigned ans{};
        // a, b の区間を昇順に見て共通部分の長さを合計する
        for (unsigned i{}; const auto &[l, r] : Sa){
        ans += clamp(Sb[i].second, l, r) - clamp(Sb[i].first, l, r);
        while (i + 1 < size(Sb) && Sb[i + 1].first <= r) {
            ++i;
            ans += clamp(Sb[i].second, l, r) - clamp(Sb[i].first, l, r);
        }
    }
        return memo[{a, b}] = ans;
    }};

    unsigned Q;
    cin >> Q;

    for (unsigned i{}, a, b; i < Q; ++i) {
        cin >> a >> b;
        --a;
        --b;
        cout << query(a, b) << endl;
    }
    return 0;
}

