    if 1 <= x <= H and 1 <= y <= W:
        ans -= 1
        erased[x][y] = 1
        if erased[x][y - 1]:
            uf_row[x].merge(y - 1, y)
        if erased[x][y + 1]:
            uf_row[x].merge(y, y + 1)
        if erased[x - 1][y]:
            uf_col[y].merge(x - 1, x)
        if erased[x + 1][y]:
            uf_col[y].merge(x, x + 1)


