    Lx, Rx = uf_col[y].get_LR(x)
    Ly, Ry = uf_row[x].get_LR(y)
    erase(Lx - 1, y)
    erase(Rx + 1, y)
    erase(x, Ly - 1)
    erase(x, Ry + 1)

