int main() {
    int n, m;
    ll k;
    cin >> n >> m >> k;
    vector<ll> a(n);
    for (auto& e : a) cin >> e;
    const ll rem = k - accumulate(a.begin(), a.end(), 0LL);

    if (n == m) {
        for (int i = 0; i < n; ++i) cout << 0 << " \n"[i == n - 1];
        return 0;
    }

    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int i, int j) { return a[i] < a[j]; });
    auto b = a;
    sort(b.begin(), b.end());
    vector<ll> sumb(n + 1);  // 昇順にしたAの累積和
    for (int i = 0; i < n; ++i) sumb[i + 1] = sumb[i] + b[i];

    vector<ll> ans(n, -1);
    for (int i = 0; i < n; ++i) {
        ll l = -1, r = rem + 1;
        while (r - l > 1) {
            ll mid = (l + r) / 2;
            ll rid = lower_bound(b.begin(), b.end(), b[i] + mid + 1) - b.begin();  // b[rid - 1]<b[i]+mid+1 となる最大のridを求めている
            ll lid = n - m - (i >= n - m ? 1 : 0);  // i<n-mの時は 候補者n-m,...,nが上位 m 人でi >=n-m の時は候補者n-m-1,...,i-1,i+1,..,.n が上位 m 人になる
            ll cnt = 0;
            if (rid > lid) cnt += (rid - lid) * (b[i] + mid + 1) - (sumb[rid] - sumb[lid]);
            if (lid <= i && i < rid)
                cnt--;  // この時、すでに候補者iが b[i]+mid+1 票獲得していることにしているので 1を引く
            else
                cnt += mid;  // 候補者 i の必要な票を加算する
            if (cnt > rem)
                r = mid;
            else
                l = mid;
        }
        if (l == rem)
            ans[ord[i]] = -1;
        else
            ans[ord[i]] = r;
    }

    for (int i = 0; i < n; ++i) cout << ans[i] << " \n"[i == n - 1];
}

editorials.text:
点 \(A,B\) について \(|AB|\) を線分 \(AB\) の長さと定義します。 実は、 \(\displaystyle \sum_{i=1}^{N}|P_i Q_{R_i}|\) の最小値を達成するような \(R\) がこの問題の解になります。 証明 まず、以下の命題が成り立つことを示します。 問題の条件を満たさない任意の \(R\) について、 \(\displaystyle \sum_{i=1}^{N}|P_i Q_{R'_i}| < \displaystyle \sum_{i=1}^{N}|P_i Q_{R_i}|\) を満たすような \(R'\) が存在する。 問題の条件を満たさない \(R\) において、線分 \(P_a Q_{R_a}\) と線分 \(P_b Q_{R_b}\) \((1 \leq a < b \leq N)\) が交わっているとします。このとき、 \(R'_k= \left \{ 
\begin{array}{ll}
R_k &(k \neq a \land k \neq b) \\
R_a &(k = b) \\
R_b &(k=a)
\end{array}
\right\}
\) となる \(R'\) は \(\displaystyle \sum_{i=1}^{N}|P_i Q_{R'_i}| < \displaystyle \sum_{i=1}^{N}|P_i Q_{R_i}|\) を満たします。
これは線分 \(P_a Q_{R_a}\) と線分 \(P_b Q_{R_b}\) の交点を \(X\) としたとき、三角形の成立条件より \(|P_aX|+|Q_{R_b}X|>|P_aQ_{R_b}|\) 及び \(|P_bX|+|Q_{R_a}X|>|P_bQ_{R_a}|\) が言え、 \(|P_aQ_{R_a}|+|P_bQ_{R_b}|>|P_aQ_{R_b}|+|P_bQ_{R_a}|\) と示せるため成り立ちます。 また、 \(\displaystyle \sum_{i=1}^{N}|P_i Q_{R_i}|\) は有界であるため最小値が存在します。
よって、先ほどの命題より \(\displaystyle \sum_{i=1}^{N}|P_i Q_{R_i}|\) の最小値を満たす \(R\) は問題文の条件を満たすことが示せます。
(証明終わり) 実際に最小値を達成するような \(R\) を求めるためには最小重み完全マッチング問題を解く必要があります。
最小重み完全マッチング問題はハンガリアン法や最小費用流を用いて高速に求めることができます。最小費用流問題について初めて知ったという方はdrkenさんの 記事 などを参照してください。また、今回の場合は同様の問題がLibrary Checkerにあります。( 問題 ) AtCodoer Library(ACL) には最小費用流ライブラリがあるため、それを用いることで簡潔に実装出来ます。ただし、ここで注意点があり、ACLの最小費用流では整数型のみを保証していて、コストの型を浮動小数点数にすることは厳密には未定義です。そのため、実際のコストをある定数 \(C\) との積を取って四捨五入した値を最小費用流で用いるコストとする必要があります。この \(C\) は今回の制約下では少なくとも \(1.413 \times 10^{12}\) 以上のときでないと正当性を示せません。座標の絶対値が \(M\) 以下であるとき、 \(C\) のオーダーはすくなくとも \(O(M^3)\) である必要があります。 しかし、この問題ではACLの最小費用流でコストの型をdouble型やlong double型としてもACが取れるようになっています。

