using namespace std;
using pi=pair<int,int>;

long double dist(pi l,pi r){
  long long v=0;
  v+=(l.first-r.first)*(l.first-r.first);
  v+=(l.second-r.second)*(l.second-r.second);
  return sqrtl(((long double)v));
}

int main(){
  int n,s,t;
  cin >> n >> s >> t;
  vector<pi> x(n),y(n);
  for(int i=0;i<n;i++){
    cin >> x[i].first >> x[i].second >> y[i].first >> y[i].second;
  }

  long double res=8e18;
  vector<int> p;
  for(int i=0;i<n;i++){
    p.push_back(i);
  }

  do{
    for(int i=0;i<(1<<n);i++){
      long double cres=0.0;
      pi cur=make_pair(0,0);
      for(int j=0;j<n;j++){
        int el=p[j];
        if(i&(1<<j)){
          cres+=( dist(cur,x[el])/((long double)s) );
          cres+=( dist(x[el],y[el])/((long double)t) );
          cur=y[el];
        }
        else{
          cres+=( dist(cur,y[el])/((long double)s) );
          cres+=( dist(y[el],x[el])/((long double)t) );
          cur=x[el];
        }
      }
      res=min(res,cres);
    }
  }while(next_permutation(p.begin(),p.end()));

  cout << fixed << setprecision(12) << res << "\n";
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

long long div_ceil(long long a,long long b){
  return (a+b-1)/b;
}

long long solve(
  long long n,long long x,vector<long long> a,vector<long long> p,vector<long long> b,vector<long long> q
){
  long long l=1,r=1000000007;
  while(l<=r){
    long long te=(l+r)/2;
    long long rem=x;

    for(long long i=0;i<n;i++){
      long long sub=4e18;
      for(long long j=0;j<=b[i];j++){
        long long cur=j*p[i];
        long long rte=max(0ll,te-a[i]*j);
        cur+=div_ceil(rte,b[i])*q[i];

        sub=min(sub,cur);
      }
      for(long long j=0;j<=a[i];j++){
        long long cur=j*q[i];
        long long rte=max(0ll,te-b[i]*j);
        cur+=div_ceil(rte,a[i])*p[i];

        sub=min(sub,cur);
      }
      rem-=sub;
      if(rem<0){break;}
    }

    if(rem>=0){l=te+1;}
    else{r=te-1;}
  }
  return r;
}

int main(){
  long long n,x;
  cin >> n >> x;
  vector<long long> a(n),p(n),b(n),q(n);
  for(int i=0;i<n;i++){
    cin >> a[i] >> p[i] >> b[i] >> q[i];
  }

  cout << solve(n,x,a,p,b,q) << "\n";
  return 0;
}

