int main(void){
	int n,m,sz;
	string s[N];
	vector<vector<int> > scc;
	int grp[N];
	bool r[N][N];

	cin>>n;
	rep(i,n)cin>>s[i];
	scc_graph g1(n);
	rep(i,n)rep(j,n){
		if(s[i][1]==s[j][0])g1.add_edge(i,j);
	}
	scc=g1.scc();
	m=scc.size();
	rep(i,m){
		sz=scc[i].size();
		rep(j,sz){
			grp[scc[i][j]]=i;
		}
	}

	rep(i,n)rep(j,n){
		if(s[i][1]==s[j][0]){
		  r[grp[i]][grp[j]]=true;
		}
	}
	for(int i=m-1;i>=0;i--){
		for(int j=i+1;j<m;j++){
			if(r[i][j]){
				for(int k=j+1;k<m;k++){
					r[i][k]|=r[j][k];
				}
			}
		}
	}

	mf_graph<int> g2(2*m+2);
	for(int i=0;i<m;i++){
		g2.add_edge(0,i+1,1);
		g2.add_edge(i+m+1,2*m+1,1);
	}
	for(int i=0;i<m;i++){
		for(int j=i+1;j<m;j++){
			if(r[i][j])g2.add_edge(i+1,j+m+1,1);
		}
	}

	cout<<(m-g2.flow(0,2*m+1))<<endl;
	return 0;
}

