int main() {
    using namespace std;
    unsigned H, W;
    cin >> H >> W;

    unsigned long X;
    unsigned x, y;
    cin >> X >> x >> y;

    // 周囲に大きすぎて吸収できないスライムを番兵として配置しておく
    // 500 × 500 × 10^12 = 2.5 × 10^19 あれば十分
    vector slime_size(H + 2, vector(W + 2, 250000000000000000UL));
    // 中央 H × W マスだけ読み込む
    for (auto &&row : slime_size | views::drop(1) | views::take(H))
        for (auto &&S : row | views::drop(1) | views::take(W))
            cin >> S;

    unsigned long now_size{slime_size[x][y]};

    vector visited(H + 2, vector(W + 2, false));

    priority_queue<tuple<unsigned long, unsigned, unsigned>, vector<tuple<unsigned long, unsigned, unsigned>>, greater<>> pq;
    pq.emplace(0, x, y);
    visited[x][y] = true;

    while (!pq.empty()) {
        const auto [size, x, y] = pq.top();
        pq.pop();

        // 接しているスライムのうち最も小さいものも吸収できなければ終了
        if (size >= (now_size + X - 1) / X)
            break;

        // スライムを吸収する
        now_size += size;

        // 新たに接したスライムを優先度付きキューに追加する
        for (const auto &[dx, dy] : vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}})
            if (!visited[x + dx][y + dy]) {
                visited[x + dx][y + dy] = true;
                pq.emplace(slime_size[x + dx][y + dy], x + dx, y + dy);
            }
    }

    cout << now_size << endl;

    return 0;
}

editorials.text:
\(\displaystyle f(X,Y)=\sum_{i=1}^X \sum_{j=1}^Y |A_i-B_j|\) とします。 この問題は Mo’s Algorithm ( クエリ平方分割 ) と呼ばれるアルゴリズムを用いることで効率的に解くことができます。
Mo’s Algorithm の概要は以下の通りです： 適当な値 \(M\) を設定する。 \(\displaystyle \left\lfloor \frac{X_k}{M} \right\rfloor\) が同じ値となるようなクエリを一つのブロックにまとめる。 各ブロックに対して以下の操作を行う： ブロック内で \(Y_k\) の昇順にソートする。 ブロック内の各クエリに対して順番に直前のクエリの答えからの答えの差分を求めることで答えを求める。 この問題で \(f(X+1,Y)-f(X,Y)\) と \(f(X,Y+1)-f(X,Y)\) がどちらも \(O(\alpha)\) で計算できると仮定した場合、上のアルゴリズムの計算量は \(\displaystyle O\left(\max\left(MK\alpha,\frac{N^2\alpha}M\right)\right)\) となります。 \(\displaystyle M=O\left(\frac{N}{\sqrt K} \right)\) と設定することで、計算量を \(O\left(N\sqrt K\alpha \right)\) にすることができます。Mo’s algorithm に関するより詳しい説明は、以下の記事などを参考にしてください。 Mo’s algorithm - アルゴリズムとデータ構造大全 Mo’s algorithm - ei1333の日記 以下は \(f(X+1,Y)-f(X,Y)\) と \(f(X,Y+1)-f(X,Y)\) を高速に計算する方法について考えます。 \(B_1,B_2,\ldots,B_{Y}\) のうち \(A_{X+1}\) 未満であるものの個数と総和をそれぞれ \(C,S\) とすると、 \[
\begin{aligned}
\displaystyle f(X+1,Y)-f(X,Y)&=\sum_{j=1}^Y |A_{X+1}-B_j|\\
&=\sum_{j=1}^Y\left( A_{X+1}+B_j-2\min(A_{X+1},B_j)  \right)\\
&=YA_{X+1}+\sum_{j=1}^Y B_j -2\left\{(Y-C)A_{X+1}+S \right\}
\end{aligned}
\] となります。ここで、この \(C\) と \(S\) の値は座標圧縮と fenwick tree を組み合わせることで求めることができます。詳しい実装方法は下の実装例などを参考にしてください。 以上を適切に実装することで本問題は計算量 \(O(N\sqrt{K}\log N)\) で解くことができます。 実装例 (Python3) 実装例(C++)

