#include <ranges>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;

    vector<unsigned> A(N);
    for (auto&& a : A)
        cin >> a;

    // 判定関数
    // K 個の鏡餅を作ることができるか？
    const auto check{
        [N, &A](unsigned K) {
            for (unsigned i = 0; i < K; ++i)
                // 先頭と末尾から K 個ずつ取ってきて
                if (A[i] * 2 > A[N - K + i])
                    // どれか 1 つでも半分より大きかったら false
                    return false;
            // そうでなければ true
            return true;
        }
    };

    // 0 から N / 2 の間で、判定関数が true になる最大の値（false になる最小の値 - 1）を二分探索で求める
    cout << *ranges::partition_point(views::iota(0U, N / 2 + 1), check) - 1 << endl;

    return 0;
}

