int main()
{
    int n;
    cin >> n;
    int B = to_string(n).size();
    vector<mint> fact(n + 1), finv(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++)
        fact[i] = i * fact[i - 1];
    finv[n] = fact[n].inv();
    for (int i = n; i > 0; i--)
        finv[i - 1] = i * finv[i];
    auto comb = [&](int n, int k) -> mint
    { return fact[n] * finv[k] * finv[n - k]; };
    vector<int> ten(B + 1);
    ten[0] = 1;
    for (int i = 1; i <= B; i++)
        ten[i] = 10 * ten[i - 1];
    vector<int> c(B + 1);
    for (int i = 1; i <= n; i++)
        c[to_string(i).size()]++;
    vector<mint> F0 = {1};
    for (int k = 1; k <= B; k++)
    {
        vector<mint> new_f(c[k] + 1);
        mint ten_c = 1;
        for (int i = 0; i < c[k] + 1; i++)
        {
            new_f[i] = comb(c[k], i) * ten_c;
            ten_c *= ten[k];
        }
        F0 = atcoder::convolution(F0, new_f);
    }
    F0.push_back(0);
    mint ans = 0;
    for (int b = 1; b <= B; b++)
    {
        auto f = F0;
        for (int i = 0; i < n; i++)
            f[i + 1] -= ten[b] * f[i];
        mint res = 0;
        for (int i = 0; i < n; i++)
            res += f[i] * fact[i] * fact[n - 1 - i];
        long long le = ten[b - 1], ri = min(ten[b], n + 1);
        ans += res * (ri * (ri - 1) / 2 - le * (le - 1) / 2);
    }
    cout << ans.val() << endl;
}

