        if (to[i] != -1) {
            if (to[i] != i) {
                ans++;
            }
            in_deg[to[i]]++;
            uf.merge(i, to[i]);
        }
    }
    vector<vector<int>> groups = uf.groups();
    for (const vector<int> &g: groups) {
        bool is_cycle = true;
        for (int i: g) {
