int main() {
	cin.tie(nullptr);
	ios::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<mint> a(n + 1);
	rep(i, n) {
		int x;
		cin >> x;
		a[i + 1] = a[i] + x;
	}
	mint ans = 0;
	rep(k, m + 1) {
		mint c = 1;
		rep(i, m) c *= i + 1;
		rep(i, k) c /= i + 1;
		rep(i, m - k) c /= i + 1;
		mint s = 0;
		rep(i, n + 1) {
			ans += a[i].pow(m - k) * s * c;
			s += (-a[i]).pow(k);
		}
	}
	cout << ans << endl;
}

