using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> id(2 * n);
    for (int i = 1; i <= m; i++) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        id[a] = id[b] = i;
    }

    vector<int> min_cov(2 * n); // min_cov[i]: smallest interval that covers point i
    int K = 1;
    while ((1 << K) <= m) ++K;
    vector par(K, vector<int>(m + 1, -1));
    vector<int> dep(m + 1);
    stack<int> st;
    st.push(0);
    for (int i = 0; i < 2 * n; i++) {
        if (i & 1) {
            if (!id[i]) continue;
            if (st.top() == id[i]) {
                st.pop();
                par[0][id[i]] = st.top();
                dep[id[i]] = st.size();
            } else {
                st.push(id[i]);
            }
        } else {
            min_cov[i] = st.top();
        }
    }
    for (int k = 0; k < K - 1; k++) {
        for (int i = 0; i < m + 1; i++) {
            par[k + 1][i] = (par[k][i] == -1 ? -1 : par[k][par[k][i]]);
        }
    }

    auto lca = [&](int u, int v) -> int {
        if (dep[u] > dep[v]) swap(u, v);
        int d = dep[v] - dep[u];
        for (int k = 0; k < K; k++) {
            if (d >> k & 1) v = par[k][v];
        }
        if (u == v) return u;
        for (int k = K - 1; k >= 0; k--) {
            if (par[k][u] != par[k][v]) {
                u = par[k][u];
                v = par[k][v];
            }
        }
        return par[0][u];
    };

    int q;
    cin >> q;
    while (q--) {
        int c, d;
        cin >> c >> d;
        --c, --d;
        int u = min_cov[c];
        int v = min_cov[d];
        int l = lca(u, v);
        cout << dep[u] + dep[v] - dep[l] * 2 << '\n';
    }
}

