  while(t>0){
    t--;
    int H,W;
    cin >> H >> W;
    vector<string> s(H);
    for(auto &nx : s){cin >> nx;}
    if(H>W){s=flip(s);}
    H=s.size();
    W=s[0].size();

    int ofs=H*W;
    vector<int> bk(2*H*W+1,0);
    long long res=0;
    for(int u=0;u<H;u++){
      vector<int> C(W,0);
      for(int d=u;d<H;d++){
        for(int i=0;i<W;i++){
          if(s[d][i]=='#'){C[i]++;}
          else{C[i]--;}
