        bk[h+ofs]++;
        for(int i=0;i<W;i++){
          h+=C[i];
          res+=bk[h+ofs];
          bk[h+ofs]++;
        }

        // reset bk
        h=0;
        bk[h+ofs]=0;
        for(int i=0;i<W;i++){
          h+=C[i];
          bk[h+ofs]=0;
        }
      }
    }
    cout << res << "\n";
  }
  return 0;
}

