using mint = atcoder::modint998244353;

int main() {
    int n, m;
    cin >> n >> m;
    vector cnt(n, vector<int>(n));
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        ++cnt[u][v];
        ++cnt[v][u];
    }

    mint ans = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            ans += mint(cnt[i][j]) * (cnt[i][j] - 1);
        }
    }
    for (int s = 3; s <= n; s++) {
        vector dp(1 << s, vector<mint>(s));
        dp[1 << (s - 1)][s - 1] = 1;
        for (int bit = 1 << (s - 1); bit < (1 << s); bit++) {
            int ppc = popcount((unsigned) bit);
            for (int i = 0; i < s; i++) {
                if (~bit >> i & 1) continue;
                if (ppc >= 3) {
                    ans += dp[bit][i] * cnt[i][s - 1];
                }
                for (int j = 0; j < s; j++) {
                    if (bit >> j & 1) continue;
                    dp[bit | 1 << j][j] += dp[bit][i] * cnt[i][j];
                }
            }
        }
    }
    ans /= 2;
    cout << ans.val() << endl;
}

