        x--, y--;
        dist[x][y] = 0;
        cnt[x][y] = 4;
        que.emplace(x, y);
    }
    long long ans = 0;
    while (!que.empty()) {
        auto [x, y] = que.front();
        que.pop();
        ans += dist[x][y];
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx < 0 || nx >= h || ny < 0 || ny >= w)
