    vector<int> dp(sz);
    for (int i = 0; i < dp.size(); i++) {
        for (auto [w, v]: ls) {
            if (i < v or i + w >= dp.size()) continue;
            dp[i + w] = max(dp[i + w], dp[i] + v);
        }
    }
