#define rep(i, n) for(int i = 0; i < n; ++i)
#define N 1000

int n,m,x,y;
vector<int>e[N];
vector<int>ans;
bool used[N];
bool cand[N];

void dfs(int k){
	cand[k]=true;
	int sz=e[k].size();
	rep(i,sz){
		if((!cand[e[k][i]])&&(!used[e[k][i]]))dfs(e[k][i]);
	}
	return;
}

void solve(void){
	ans.clear();
	int cur = x;
	while(cur!=y){
		ans.push_back(cur);
		used[cur]=true;
		rep(i,n)cand[i]=false;
		dfs(y);
		int sz=e[cur].size();
		int nxt=n;
		rep(i,sz)if(cand[e[cur][i]])nxt=min(nxt,e[cur][i]);
		cur=nxt;	
	}
	ans.push_back(y);
	return;
}


int main(void){
	int t;
	cin >> t;
	rep(_,t){
		cin >> n >> m >> x >> y;
		x--,y--;
		rep(i,n)used[i]=false;
		int u,v;
		rep(i,m){
			cin >> u >> v;
			e[u-1].push_back(v-1);
			e[v-1].push_back(u-1);
		}
		solve();
		int sz = ans.size();
		rep(i,sz-1)cout << (ans[i]+1) << " ";
		cout << (ans[sz-1]+1) << endl;
		rep(i,n)e[i].clear();
	}
	return 0;
}

#include <iostream>
#include <optional>
#include <atcoder/lazysegtree>
#include <atcoder/modint>

int main() {
    using namespace std;
    using modint = atcoder::static_modint<998244353>;
    // (区間の長さ, 区間の総和) を管理する遅延セグメント木
    using segtree = atcoder::lazy_segtree<
        pair<unsigned, modint>,
        [](const auto& lhs, const auto& rhs){return make_pair(lhs.first + rhs.first, lhs.second + rhs.second);},
        []{return pair<unsigned, modint>{};},
        optional<modint>,
        [](const auto& a, const auto& b){return a ? make_pair(b.first, b.first * *a) : b;},
        [](const auto& a, const auto& b){return a ? a : b;},
        []{return nullopt;}
    >;

    unsigned N, M;
    cin >> N >> M;
    segtree expected_value(N);
    for (unsigned i{}, A; i < N; ++i) {
        cin >> A;
        expected_value.set(i, {1, A});
    }
    for (unsigned i{}, L, R; i < M; ++i) {
        cin >> L >> R;
        --L; // 0-indexed 半開区間にする
        const auto sum{expected_value.prod(L, R).second}; // 区間の総和を求めて
        expected_value.apply(L, R, sum / (R - L)); // 全体に代入
    }

    for (unsigned i{}; i < N; ++i)
        cout << expected_value.get(i).second.val() << " ";
    cout << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(long long i = 0; i < n; ++i)
#define ll long long
#define Q 500010
#define K 20
#define LMAX (ll)1e+18

struct seg{
	long long idx;
	long long ofs;
};

ll len[Q];
seg lgt[Q];
seg hev[Q][K];

void init(void){
	rep(i,Q){
		len[i]=-1;
		lgt[i]={-1,-1};
		rep(j,K)hev[i][j]={-1,-1};
	}
	len[0]=1,len[1]=1;
	return;
}

void concat_seg(long long nidx, long long le,long long ri){
	ll nlen=len[le]+len[ri];
	if(nlen>LMAX)nlen=LMAX;
	len[nidx]=nlen;
	ll llen=len[le];
	ll rlen=nlen-llen;
	if(llen<rlen){
		lgt[nidx]={le,0};
		hev[nidx][0]={ri,llen};
		long long cur=ri;
		ll curofs=llen;
		for(long long i=1;i<K;i++){
			curofs+=hev[cur][i-1].ofs;
			cur=hev[cur][i-1].idx;
			if(cur==-1)break;
			if(curofs>LMAX)break;
			hev[nidx][i]={cur,curofs};
		}
	}
	else{
		lgt[nidx]={ri,llen};
		hev[nidx][0]={le,0};
		long long cur=le;
		ll curofs=0;
		for(long long i=1;i<K;i++){
			curofs+=hev[cur][i-1].ofs;
			cur=hev[cur][i-1].idx;
			if(cur==-1)break;
			if(curofs>LMAX)break;
			hev[nidx][i]={cur,curofs};
		}
	}
	return;
}

long long search(long long k,long long x){
	if(k<=1)return k;
	long long curk=k, curx=x;
	for(long long i=19;i>=0;i--){
		if(hev[curk][i].idx==-1)continue;
		if((hev[curk][i].ofs<=curx)&&(curx<(hev[curk][i].ofs+len[hev[curk][i].idx]))){
			curx-=hev[curk][i].ofs;
			curk=hev[curk][i].idx;
		}
	}
	while(lgt[curk].idx!=-1){
		if((lgt[curk].ofs<=curx)&&(curx<(lgt[curk].ofs+len[lgt[curk].idx]))){
			curx-=lgt[curk].ofs;
			curk=lgt[curk].idx;
		}
		else break;
	}
	return search(curk,curx);
}



int main() {
	long long q,le,ri,x;
	init();
	cin>>q;
	rep(qq,q){
		cin>>le>>ri>>x;
		concat_seg(qq+2,le,ri);
		cout<<search(qq+2,x-1)<<endl;
	}

	return 0;
}

