int main(){
    using namespace std;
    long X;
    cin >> X;

    // 探索する k の範囲
    // abs(X) は double で正確に表現できるので、この平方根の小数点以下を切り捨てた値も正確に得られる
    long bound = sqrt(abs(X)) + 1;

    vector<long> ans;
    for (long k{-bound + 1}; k <= bound; ++k)
        if ((X - k * k) % (2 * k - 1) == 0) { // 割り切れることが必要
            // n ≧ 0 かつ n + k ≧ 0 なら OK
            auto n = (X - k * k) / (2 * k - 1);
            if (n >= 0 && n + k >= 0) {
                ans.emplace_back(n);
                ans.emplace_back(-n - 1);
            }
        }

    ranges::sort(ans);

    cout << size(ans) << endl;
    for (const auto n : ans)
        cout << n << endl;

    return 0;
}

