  ll len;
  ll res;
}S;

S e(){ return {0,0,0}; }
S op(S l,S r){
  S res;
  res.val=l.val+r.val;
  res.len=l.len+r.len;
  res.res=l.res+r.res;
  res.res+=l.len*r.val;
  res.res-=l.val*r.len;
  return res;
}

