    // 末尾の要素を使うものも同時に求める
    const auto solve{[M](const auto& seq) -> pair<vector<unsigned>, vector<unsigned>> {
        vector<unsigned> used, unused;
        unused.emplace_back();
        for (const auto x : seq) {
            swap(used, unused);
            for (auto&& v : used) {
                unused.emplace_back(v);
                (v += x) %= M;
