        vector<unsigned> all(used);
        ranges::copy(unused, back_inserter(all));
        ranges::sort(used);
        ranges::sort(all);
        return make_pair(used, all);
    }};

    // 前半に対する結果
    const auto [first_used, first_all]{solve(A | views::take(N / 2))};
    // 後半に対する結果
    const auto [second_used, second_all]{solve(A | views::reverse | views::take((N + 1) / 2))};

    unsigned long ans{};
    for (const auto a : first_all)
        ans += ranges::upper_bound(second_all, (M - a) % M) - ranges::lower_bound(second_all, (M - a) % M);

    // 境界で連続しているものを引く
    for (const auto a : first_used)
        ans -= ranges::upper_bound(second_used, (M - a) % M) - ranges::lower_bound(second_used, (M - a) % M);

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <ranges>
#include <algorithm>

int main() {
    using namespace std;
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    unsigned N;
    long A, B;
    cin >> N >> A >> B;
    vector<long> P(N);
    for (auto&& p : P)
        cin >> p;

    // 良い列の列
    vector<vector<long>> seq;

    // 十分小さい値
    static constexpr long min_sentinel{-800000000000000};

    // 2 つの良い列をマージして等価なひとつの良い列を作る
    const auto merge{[N, A, B](auto&& lhs, auto&& rhs) -> vector<long> {
        const long L(size(lhs)), R(size(rhs));
        vector<long> result;
        result.emplace_back(min_sentinel); // 番兵
        result.reserve(L + R + 1);
        for (long l{}, r{}; l < L || r < R; )
            // 先頭から値を決める
            result.emplace_back(l == L || (r < R && lhs[l] - r * B > rhs[r] - (L - l) * A) ?
                                rhs[r++] - (L - l) * A :
                                max(result.back() + A, lhs[l++] - r * B));
        result.erase(begin(result)); // 番兵を消す
        return result;
    }};

    // 新しい列を追加する
    // 末尾と長さが等しければ、末尾を取り出してマージ
    const auto append_seq{[&seq, &merge](const auto& rec, vector<long>&& p) -> void {
        if (empty(seq) || size(seq.back()) != size(p))
            seq.emplace_back(move(p));
        else {
            auto lhs{move(seq.back())};
            seq.pop_back();
            rec(rec, merge(move(lhs), move(p)));
        }
    }};

    for (const auto p : P)
        append_seq(append_seq, vector{p});

    unsigned Q;
    cin >> Q;

    for (unsigned i{}; i < Q; ++i) {
        unsigned T;
        long X;
        cin >> T >> X;
        if (T == 1)
            append_seq(append_seq, vector{X});
        else {
            for (const auto& s : seq) // 良い列ごとに
                // 二分探索をしてテンションの変化を求める
                X += A * size(s) - (A + B) * *ranges::partition_point(views::iota(0UL, size(s)), [X, &s, B](const long i){
                    return X > s[i] + i * B;
                });
            cout << X << '\n';
        }
    }
    cout << flush;

    return 0;
}

