typedef long long int ll;

// floor(sqrt(x))
ll f (ll x) {
	ll y = sqrt(x);
	while (y * y > x) y--;
	while ((y+1) * (y+1) <= x) y++;
	return y;
}
ll solve (ll c, ll d) {
	ll ans = 0;

	ll xmin = 1, xmax = 9, cshift = 10;
	while (xmin <= c + d) {
		ll l = max(xmin, c + 1);
		ll r = min(xmax, c + d);

		if (l <= r) {
			ll vl = c * cshift + l;
			ll vr = c * cshift + r;

			ans += (f(vr) - f(vl - 1));
		}

		xmin = xmin * 10;
		xmax = (xmax + 1) * 10 - 1;
		cshift *= 10;
	}

	return ans;
}

int main (void) {
	ll T;
	cin >> T;

	for (ll ti = 0; ti < T; ti++) {
		ll c, d;
		cin >> c >> d;

		ll ans = solve(c, d);
		cout << ans << "\n";
	}


	return 0;
}

