typedef long long int ll;

ll n, q;
vector<ll> w;

typedef struct {
	ll li;
	ll ri;
	ll gravity;
	ll x;
} Block;
vector<Block> bar;

void barclear (ll v, ll dir) {
	while (true) {
		Block b = bar.back();
		bar.pop_back();

		if (b.ri >= v) {
			if (v+1 <= b.ri) {
				bar.push_back({v+1, b.ri, b.gravity, b.x});
			}
			ll fl, fr;
			if (b.gravity < 0) {
				fl = b.x;
				fr = fl + w[v];
			} else {
				fr = b.x;
				fl = fr - w[v];
			}
			ll currx = ((dir < 0) ? fl : fr);
			bar.push_back({0, v, dir, currx});
			break;
		}
	}
}

int main (void) {
	cin >> n;
	w.resize(n);
	for (ll i = 0; i < n; i++) {
		cin >> w[i];
	}

	// init
	bar.push_back({0, n-1, -1, 0});

	cin >> q;
	for (ll qi = 0; qi < q; qi++) {
		ll type;
		cin >> type;
		if (type == 1) {
			ll v;
			cin >> v;
			--v;
			// type 1
			barclear(v, -1);
		} else if (type == 2) {
			ll v;
			cin >> v;
			--v;
			// type 2
			barclear(v, +1);
		} else if (type == 3) {
			ll x;
			cin >> x;
			// type 3
			ll ans;
			ll idx;
			{
				ll ok = -1, ng = bar.size();
				while (ok + 1 < ng) {
					ll med = (ok + ng) / 2;
					ll fl, fr;
					if (bar[med].gravity < 0) {
						fl = bar[med].x;
						fr = fl + w[bar[med].ri];
					} else {
						fr = bar[med].x;
						fl = fr - w[bar[med].ri];
					}
					if (fl <= x && x < fr) {
						ok = med;
					} else {
						ng = med;
					}
				}
				idx = ok;
			}
			if (idx < 0) {
				ans = 0;
			} else {
				ll fl, fr;
				ll ok = bar[idx].ri, ng = bar[idx].li - 1;
				while (ng + 1 < ok) {
					ll med = (ok + ng) / 2;
					if (bar[idx].gravity < 0) {
						fl = bar[idx].x;
						fr = fl + w[med];
					} else {
						fr = bar[idx].x;
						fl = fr - w[med];
					}
					if (fl <= x && x < fr) {
						ok = med;
					} else {
						ng = med;
					}
				}
				ans = n - ok;
			}

			cout << ans << "\n";
		}

	}

	return 0;
}

