int nearest(int x,set<int> &st){
  auto it=st.find(x);
  int res=2e9;
  if(it!=st.begin()){
    auto jt=it; jt--;
    res=min(res,x-(*jt));
  }
  it++;
  if(it!=st.end()){
    res=min(res,(*it)-x);
  }
  return res;
}

