using ll=long long;
struct S{
	// aaa=\cap S_i, ooo=\cup S_i
	// max=\max(#S_i), cnt=#{i|#S_i=max}
	ll aaa,ooo;
	int max,cnt;
	bool fail;
};
struct F{
	// f(x)=(x \cap aaa) \cup ooo;
	ll aaa,ooo;
};
S e(){
	return{-1,0,0,0,false};
}
F id(){
	return{-1,0};
}
S op(S x,S y){
	S ret;
	ret.aaa=x.aaa&y.aaa;
	ret.ooo=x.ooo|y.ooo;
	if(x.max>y.max){
		ret.max=x.max;
		ret.cnt=x.cnt;
	}else if(x.max<y.max){
		ret.max=y.max;
		ret.cnt=y.cnt;
	}else{
		ret.max=x.max;
		ret.cnt=x.cnt+y.cnt;
	}
	ret.fail=false;
	return ret;
}
S mapping(F f,S x){
	if((x.ooo^x.aaa)&(~f.aaa|f.ooo)){
		//fail
		return {0,0,0,0,true};
	}
	S ret=x;
	ret.max-=__builtin_popcountll(ret.aaa&~f.aaa);
	ret.aaa&=f.aaa;
	ret.ooo&=f.aaa;
	ret.max+=__builtin_popcountll(~ret.ooo&f.ooo);
	ret.aaa|=f.ooo;
	ret.ooo|=f.ooo;
	return ret;
}
F composition(F g,F f){
	F ret;
	ret.aaa=f.aaa&g.aaa;
	ret.ooo=(f.ooo&g.aaa)|g.ooo;
	return ret;
}

// atcoder::lazy_segtree のメンバ関数 all_apply を以下のように変更
void all_apply(int k, F f) {
    d[k] = mapping(f, d[k]);
    if (k < size) {
        lz[k] = composition(f, lz[k]);
        if (d[k].fail) push(k), update(k);  // <-- add
    }
}

