  for (int i = 0; i < N; i++) cin >> X[i] >> R[i];

  set<int> st;
  for (int i = 0; i < N; i++) {
    int xpr = X[i] + R[i];
    int xmr = X[i] - R[i];
    st.insert(xpr), st.insert(xmr);
  }

  vector<int> coords;
  for (auto& s : st) coords.push_back(s);
  int M = coords.size();

  int source = N + M;
  int sink = source + 1;
  atcoder::mf_graph<int> g(sink + 1);

  for (int i = 0; i < N; i++) {
    g.add_edge(source, i, 1);
  }
  for (int i = 0; i < N; i++) {
    int xpr = X[i] + R[i];
