                ls[s[i][j] - 'a'].emplace_back(i, j);
            }
        }
    }

    vector d(h, vector<int>(w, inf));
    queue<pair<int, int>> q;
    vector<bool> seen(26);
    d[0][0] = 0;
    q.emplace(0, 0);
    while (!q.empty()) {
        auto [i, j] = q.front();
        q.pop();
        for (int k = 0; k < 4; k++) {
            int ni = i + dx[k];
            int nj = j + dy[k];
            if (ni < 0 or ni >= h or nj < 0 or nj >= w) continue;
            if (s[ni][nj] == '#') continue;
            if (d[ni][nj] == inf) {
                d[ni][nj] = d[i][j] + 1;
                q.emplace(ni, nj);
            }
        }
        if (islower(s[i][j])) {
            int c = s[i][j] - 'a';
            if (seen[c]) continue;
            seen[c] = true;
            for (auto [ni, nj]: ls[c]) {
                if (d[ni][nj] == inf) {
                    d[ni][nj] = d[i][j] + 1;
                    q.emplace(ni, nj);
                }
            }
        }
    }

    int ans = d[h - 1][w - 1];
    cout << (ans == inf ? -1 : ans) << endl;
}

