#include<bits/stdc++.h>

using namespace std;
using ll=long long;
using pl=pair<ll,ll>;

ll solve(vector<ll> &v7,vector<ll> &v5,vector<ll> &v3){
  ll res=ssize(v7);
  res*=ssize(v5);
  res*=ssize(v3);
  if(res==0){return 0;}

  vector<pl> vp;
  for(auto &nx : v7){vp.push_back({nx,7});}
  for(auto &nx : v5){vp.push_back({nx,5});}
  for(auto &nx : v3){vp.push_back({nx,3});}
  sort(vp.begin(),vp.end());
  ll p7=0,s7=v7.size();
  ll p3=0,s3=v3.size();
  for(auto &nx : vp){
    if(nx.second==7){
      p7++; s7--;
    }
    else if(nx.second==5){
      res-=p7*s3;
      res-=p3*s7;
    }
    else if(nx.second==3){
      p3++; s3--;
    }
  }
  return res;
}

