const ll mod=998244353;

int main(){
  ll n;
  cin >> n;
  vector<ll> p(n);
  for(auto &nx : p){cin >> nx;}

  vector<ll> beg(n),fin(n);
  tree<ll,null_type,less<ll>,rb_tree_tag,tree_order_statistics_node_update> tr;
  for(ll i=0;i<n;i++){
    beg[i]=tr.order_of_key(p[i]);
    tr.insert(p[i]);
  }
  tr.clear();
  for(ll i=n-1;i>=0;i--){
    fin[i]=tr.order_of_key(p[i]);
    tr.insert(p[i]);
  }

  ll res=0;
  for(ll i=0;i<n;i++){
    res+=beg[i]*fin[i];
    res%=mod;
  }
  ll s=0;
  for(ll i=0;i<n;i++){
    res+=s*fin[i];
    res%=mod;
    s=(2*s+beg[i])%mod;
  }
  cout << res << "\n";
  return 0;
}

