int main() {
    using namespace std;
    int N;
    cin >> N;

    vector<int> A(N);
    for (auto&& a : A) {
        cin >> a;
        --a; // 0-indexed にしておく
    }

    vector<int> ans(N);
    for (int i : views::iota(0, N) | views::reverse) { // 降順に、最後に到着するマスを求める
        if (i == A[i]) { // はじめから動かないなら
            ans[i] = i; // そのマスが答え
        } else { // 動くなら
            ans[i] = ans[A[i]]; // 動いた先のマスから始めたときの結果が答え
        }
    }

    for (int a : ans) {
        // 1-indexed に直して出力
        cout << a + 1 << " ";
    }
    cout << endl;

    return 0;
}

