#include <bits/stdc++.h>
using namespace std;

int main()
{
    int H, W, N;
    cin >> H >> W >> N;
    vector<int> h(N), w(N);
    for (int i = 0; i < N; i++) cin >> h[i] >> w[i];

    // ord_h, ord_w : ピースの番号の並び替え
    // h[ord_h[i]] >= h[ord_h[i + 1]]
    // w[ord_w[i]] >= w[ord_w[i + 1]]
    vector<int> ord_h(N), ord_w(N);
    iota(ord_h.begin(), ord_h.end(), 0);
    sort(ord_h.begin(), ord_h.end(), [&](int x, int y) { return h[x] > h[y]; });
    iota(ord_w.begin(), ord_w.end(), 0);
    sort(ord_w.begin(), ord_w.end(), [&](int x, int y) { return w[x] > w[y]; });

    vector<int> ans_x(N, -1), ans_y(N, -1);
    vector<bool> used(N, false);
    auto ith = ord_h.begin();
    auto itw = ord_w.begin();
    for (int rem = N; rem > 0; rem--) {
        // すでに使用済みなら飛ばす
        while (used[*ith]) ith++;
        while (used[*itw]) itw++;
        // ピース i が縦 H ブロック or 横 W ブロック
        int i = h[*ith] == H ? *ith : *itw;
        // 右下に置く
        ans_x[i] = H - h[i] + 1;
        ans_y[i] = W - w[i] + 1;
        used[i] = true;
        if (h[i] == H) {
            W -= w[i];
        } else {
            H -= h[i];
        }
    }
    for (int i = 0; i < N; i++) cout << ans_x[i] << " " << ans_y[i] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
#include <atcoder/modint>
using mint = atcoder::modint998244353;
int main()
{
    const int M = 1e7;
    // 線形篩
    vector<int> lpf(M + 1);
    iota(lpf.begin(), lpf.end(), 0);
    vector<int> primes;
    for (int x = 2; x <= M; x++)
    {
        if (lpf[x] == x) primes.push_back(x);
        for (auto p : primes) {
            if ((int64_t)p * x > M || p > lpf[x]) break;
            lpf[p * x] = p;
        }
    }
    int T;
    cin >> T;
    while (T--)
    {
        int N;
        cin >> N;
        vector<int> A(N);
        for (int i = 0; i < N; i++) cin >> A[i];

        // e1[p]=e_1(p), e2[p]=e_2(p)
        map<int, int> e1, e2;
        // e_1(p), e_2(p) を計算
        for (int i = 0; i < N; i++)
        {
            int x = A[i];
            while (x > 1)
            {
                int p = lpf[x], e = 0;
                while (x % p == 0) x /= p, e++;
                if (e > e1[p])
                    e2[p] = e1[p], e1[p] = e;
                else if (e > e2[p])
                    e2[p] = e;
            }
        }

        // LCM(A_1,...,A_N) を計算
        mint lcm = 1;
        for (auto &[p, e] : e1) lcm *= mint(p).pow(e);

        // 答えを計算
        for (int i = 0; i < N; i++)
        {
            mint ans = lcm;
            int x = A[i];
            while (x > 1)
            {
                int p = lpf[x], e = 0;
                while (x % p == 0) x /= p, e++;
                if (e == e1[p]) ans /= mint(p).pow(e1[p] - e2[p]);
            }
            cout << ans.val() << " \n"[i + 1 == N];
        }
    }
}

#include <iostream>
#include <vector>
#include <ranges>
#include <algorithm>

int main() {
    using namespace std;
    unsigned N, K;
    cin >> N >> K;
    vector C(N, vector<unsigned long>(N));

    for (auto&& row : C)
        for (auto&& c : row)
            cin >> c;

    // a 回移動した結果と b 回移動した結果から a + b 回移動した結果を求める
    const auto prod{[N, inf{ranges::max(C | views::join) * K}](const auto& lhs, const auto& rhs) {
        // 十分大きな値で初期化しておく
        vector ret(N, vector(N, inf));
        for (const auto i : views::iota(0U, N))
            for (const auto j : views::iota(0U, N))
                for (const auto k : views::iota(0U, N))
                    ret[i][k] = min(ret[i][k], lhs[i][j] + rhs[j][k]);
        return ret;
    }};

    auto ans(C);
    --K;

    // 繰り返し二乗法
    while (K) {
        if (K & 1)
            ans = prod(ans, C);
        C = prod(C, C);
        K /= 2;
    }

    for (const auto i : views::iota(0U, N))
        cout << ans[i][i] << endl;
    return 0;
}

#include <iostream>
#include <ranges>
#include <vector>
#include <utility>
#include <atcoder/maxflow>

int main() {
    using namespace std;
    unsigned N, A, B;
    cin >> N >> A >> B;
    // block × block マスを一塊にして塗る
    const auto block{(A | B) & -(A | B)};

    // 最大流を求めるグラフ：ソース + マス目 + シンク
    atcoder::mf_graph<int> graph(1 + N * N + 1);

    // 盤面を読み込む
    const auto field = views::istream<string>(cin) | ranges::to<vector<string>>();

    // それぞれの空きマスについて、ソースかシンクとの間に辺を張る
    for (const auto& [i, j] : views::cartesian_product(views::iota(0U, N), views::iota(0U, N)) |
                              views::filter([&field](const auto& box) {
                                  const auto& [i, j]{box};
                                  return field[i][j] == '.';
                              }))
        if (block & (i ^ j & (A ^ B)))
            graph.add_edge(0, 1 + i * N + j, 1);
        else
            graph.add_edge(1 + i * N + j, 1 + N * N, 1);

    // 同時に置くことができない空きマスの組の間に辺を張る
    for (const auto& [di, dj] : vector<pair<unsigned, unsigned>>{{A, B}, {B, A}, {-B, A}, {-A, B}})
        for (const auto& [i, j] : views::cartesian_product(views::iota(0U, N), views::iota(0U, N)) |
                                  views::filter([N, di, dj, &field](const auto& box) {
                                      const auto& [i, j]{box};
                                      return i + di < N && j + dj < N && field[i][j] == '.' && field[i + di][j + dj] == '.';
                                  }))
            if (block & (i ^ j & (A ^ B)))
                graph.add_edge(1 + i * N + j, 1 + (i + di) * N + j + dj, 1);
            else
                graph.add_edge(1 + (i + di) * N + j + dj, 1 + i * N + j, 1);

    // フローを流し、最大独立集合を求める
    graph.flow(0, 1 + N * N);
    for (const auto min_cut{graph.min_cut(0)}; const auto i : views::iota(0U, N)) {
        for (const auto j : views::iota(0U, N))
            if (field[i][j] == '#')
                cout << '#';
            else if (block & (i ^ j & (A ^ B)))
                cout << (min_cut[1 + i * N + j] ? 'o' : '.');
            else
                cout << (min_cut[1 + i * N + j] ? '.' : 'o');
        cout << endl;
    }
    return 0;
}

