typedef long long int ll;

ll m, a, b;

vector<vector<ll> > edges;
vector<ll> isseen;
void solve () {
	// backward edges
	edges.resize(m*m);
	for (ll i = 0; i < m; i++) {
		for (ll j = 0; j < m; j++) {
			// (i, j) <- (j, i*b+j*a)
			ll k = (i * b + j * a) % m;
			edges[j * m + k].push_back(i * m + j);
		}
	}

	// bfs init
	isseen.assign(m*m, 0);
	queue<ll> que;
	for (ll i = 0; i < m; i++) {
		for (ll j = 0; j < m; j++) {
			if (i == 0 || j == 0) {
				ll v = i*m + j;
				isseen[v] = 1;
				que.push(v);
			}
		}
	}
	// bfs run
	while (!que.empty()) {
		ll v = que.front();
		que.pop();

		for (ll u : edges[v]) {
			if (!isseen[u])	{
				isseen[u] = 1;
				que.push(u);
			}
		}
	}

	// count answers
	ll ans = 0;
	for (ll i = 0; i < m; i++) {
		for (ll j = 0; j < m; j++) {
			if (isseen[i * m + j] == 0) ans++;
		}
	}

	cout << ans << "\n";

}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> m >> a >> b;

	solve();

	return 0;
}

enum class State {
    OK, NG, UNKNOWN
}
class Solver(val M: Int, val A: Int, val B: Int) {
    val memo = Array(M) { Array(M) { State.UNKNOWN } }
}

fun solve(x: Int, y: Int): State {
    if (memo[x][y] == State.UNKNOWN) {
        memo[x][y] = State.OK
        val next = (A * y + B * x) % M
        memo[x][y] = if (x == 0 || y == 0) State.NG else solve(y, next)
    }
    return memo[x][y]
}

enum class State {
    OK, NG, UNKNOWN
}
class Solver(val M: Int, val A: Int, val B: Int) {
    val memo = Array(M) { Array(M) { State.UNKNOWN } }
    fun solve(x: Int, y: Int): State {
        if (memo[x][y] == State.UNKNOWN) {
            memo[x][y] = State.OK
            val next = (A * y + B * x) % M
            memo[x][y] = if (x == 0 || y == 0) State.NG else solve(y, next)
        }
        return memo[x][y]
    }
    fun ans(): Int {
        return (0 until M).sumOf { i ->
            (0 until M).count { j -> solve(i, j) == State.OK }
        }
    }
}
