using namespace std;
using ll=long long;

ll mod;

ll power(ll a,ll b){ // a^b
  ll res=1,cur=a;
  while(b>0){
    if(b&1ll){
      res*=cur; res%=mod;
    }
    cur*=cur; cur%=mod;
    b>>=1;
  }
  return res;
}

int main(){
