  }

  vector<ll> pow_keep(30); // 10^{2^d}
  pow_keep[0]=10;
  for(ll d=1;d<30;d++){
    pow_keep[d]=(pow_keep[d-1]*pow_keep[d-1])%mod;
  }

  vector<ll> Rpow2(30);
  Rpow2[0]=1;
  for(ll d=1;d<30;d++){
    Rpow2[d]=(Rpow2[d-1]*pow_keep[d-1]+Rpow2[d-1])%mod;
  }

  ll res=0;
  ll dgt=0;
  for(ll i=k-1;i>=0;i--){
    ll ce=(c[i]*power(10,dgt))%mod;
    ll R=0;
    for(ll d=29;d>=0;d--){
      if(l[i]&(1ll<<d)){
        R=(R*pow_keep[d]+Rpow2[d])%mod;
      }
    }
    res+=ce*R; res%=mod;
    dgt+=l[i];
  }
  cout << res/m << "\n";
  return 0;
}

