void solve () {
	// line up their indexs
	a.insert(a.begin(), 0);
	n++;
	b.insert(b.begin(), 0);
	m++;

	// sum[i]  := sum_{k < i} a[k] * 1
	// sum2[i] := sum_{k < i} a[k] * k
	vector<mint> sum(n+1, 0), sum2(n+1, 0);
	for (ll i = 0; i < n; i++) {
		sum[ i+1] = sum[ i] + a[i] * 1;
		sum2[i+1] = sum2[i] + a[i] * i;
	}

	mint ans = 0;
	for (ll bi = 1; bi < m; bi++) {
		mint bans = 0;
		for (ll i = 0; i * bi < n; i++) {
			ll l = (i+0) * bi;
			ll r = min((i+1) * bi, n);

			// sum_{l <= k < r} a[k] * (k - i*bi)
			bans += (sum2[r] - sum2[l]);
			bans -= (sum[r] - sum[l]) * (i*bi);
		}
		ans += bans * b[bi];
	}

	cout << ans.val() << "\n";
}

