    }

    auto f = [&](int l, int r) -> mint {
        r = min(r, N+1); // N+1 とのminをとると、 i > N となる A_i を陽に持たなくても良いです。

        return (acc_C[r] - acc_C[l]) - l * (acc_A[r] - acc_A[l]);
    };

    mint ans = 0;
    for (int j = 1; j <= M; j++) {
        mint x = 0;
        for (int k = 0; k < (N+1 + j - 1) / j; k++) {
            x += f(j*k, j*k + j);
        }
        ans += x * B[j];
    }
    cout << ans.val() << endl;
}

#include <iostream>
#include <vector>
#include <ranges>
#include <atcoder/fenwicktree>

int main() {
    using namespace std;
    unsigned N;
    unsigned long K;
    cin >> N >> K;
    vector<unsigned> P(N);
    for (auto&& p : P) {
        cin >> p;
        --p;
    }

    // f(K) を求める関数
    const auto solve{[N, &P](unsigned long K) {
        atcoder::fenwick_tree<unsigned> bit(N); // 一点更新区間和を求める
        unsigned long now{}; // 現在の転倒数
        unsigned long ans{}; // 条件を満たす区間の総数
        for (unsigned l{}, r{}; l < N; ++l) { // 尺取り法を行う
            if (r < l) r = l; // 空なら i と同時に進めておく
            while (r < N && now + bit.sum(P[r], N) <= K) { // 追加しても転倒数が K を越えないなら
                now += bit.sum(P[r], N); // r を追加する
                bit.add(P[r], 1);
                ++r;
            }
            ans += r - l; // 左端が l である条件を満たす区間は r - l 個
            now -= bit.sum(0, P[l]); // l を外す
            bit.add(P[l], -1);
        }
        return ans;
    }};

    cout << solve(K) - (K ? solve(K - 1) : 0) << endl; // f(K) - f(K - 1) が答え
    return 0;
}

