int wsum,cent;
vector<int>llist[N];

void dfs(int p,int k){
	int sz=e[k].size();
	if(sz==1)w[k]=1;
	else w[k]=0;
	bool ok=true;
	rep(i,sz){
		if(e[k][i]!=p){
			dfs(k,e[k][i]);
			w[k]+=w[e[k][i]];
			int tmp=w[e[k][i]];
			if(sz==1)tmp++;
			if(tmp*2>wsum)ok=false;
		}
	}
	if(ok&&(wsum<=w[k]*2))cent=k;
	return;
}

void dfs2(int p,int k,int idx){
	int sz=e[k].size();
	if(sz==1)llist[idx].push_back(k);
	rep(i,sz){
		if(e[k][i]!=p){
			dfs2(k,e[k][i],idx);
		}
	}
	return;
}

int main(void){
	pair<int,int> pr,ps;
	int ans[N];
	int u,v;
	int t;
	cin>>t;
	rep(tt,t){
		cin>>n>>k;
		rep(i,n-1){
			cin>>u>>v;
			e[u-1].push_back(v-1);
			e[v-1].push_back(u-1);
		}
		rep(i,k)cin>>c[i];

