				llist[i].clear();
			}
			continue;
		}

		wsum=0;
		rep(i,n){
			if(e[i].size()==1)wsum++;
		}
		dfs(-1,0);
		int sz=e[cent].size();
		priority_queue<pair<int,int> >pq;
		rep(i,sz){
			dfs2(cent,e[cent][i],i);
			pq.push({llist[i].size(),i});
		}
		rep(i,n)ans[i]=-1;
		rep(i,k){
			if(wsum==0)break;
			if(c[i]>1){
				if(wsum==1){
					while(!pq.empty()){
						pr=pq.top();
						ans[llist[pr.second][0]]=i+1;
						c[i]--;
						wsum--;
						pq.pop();
					}
					ans[cent]=i+1;	
					c[i]--;
				}
				else if(wsum<=c[i]){
					while(!pq.empty()){
						pr=pq.top();
						rep(j,pr.first){
							ans[llist[pr.second][j]]=i+1;
							c[i]--;
							wsum--;
						}
						pq.pop();
					}
				}
				else{
					pr=pq.top();
					pq.pop();
					ps=pq.top();
					pq.pop();
					ans[llist[pr.second][pr.first-1]]=i+1;
					ans[llist[ps.second][ps.first-1]]=i+1;
					if(pr.first>1)pq.push({pr.first-1,pr.second});
					if(ps.first>1)pq.push({ps.first-1,ps.second});
					c[i]-=2;
					wsum-=2;
					rep(j,c[i]){
						pr=pq.top();
						pq.pop();
						ans[llist[pr.second][pr.first-1]]=i+1;
						if(pr.first>1)pq.push({pr.first-1,pr.second});
						wsum--;
					}
					c[i]=0;
				}
			}
		}
		if(wsum>0){
			cout<<-1<<endl;
		}
		else{
			int cur=0;
			rep(i,n){
				if(ans[i]<0){
					while(c[cur]<=0)cur++;
					ans[i]=cur+1;
					c[cur]--;
				}
				cout<<ans[i];
				if(i<(n-1))cout<<" ";
				else cout<<endl;
			}
		}
		rep(i,n){
			e[i].clear();
			llist[i].clear();
		}
	}

	return 0;
}

