      for(ll i=0;i<vn;i++){
        for(ll j=0;j<vn;j++){
          nvec[j]+=vec[i]*mat[i][j];
          nvec[j]%=mod;
        }
      }
      vec=nvec;
    }
    mat=mmul(mat,mat);
    n>>=1;
  }
