ll subp(vector<ll> &a,ll k){
  ll n=a.size();
  ll r1=0,r2=0,res=0;
  for(ll l=0;l+1<n;l++){
    r1=max(r1,l+1); r2=max(r2,l+1);
    while(r1<n && a[r1]-a[l]<k){r1++;}
    while(r2<n && a[r2]-a[l]<=k){r2++;}
    res+=(r2-r1);
  }
  return res;
}

