vector<string> rotate(vector<string> a) {
    int h = a.size(), w = a[0].size();
    vector<string> res(w, string(h, '.'));
    for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) {
        res[j][h - 1 - i] = a[i][j];
    }
    return res;
}

