tuple<long long, long long, long long> get_canonical(long long px, long long py,
                                                     long long qx,
                                                     long long qy) {
  long long a = 2 * (qx - px);
  long long b = 2 * (qy - py);
  long long c = px * px + py * py - qx * qx - qy * qy;
  long long g = gcd(a, gcd(b, c));
  a /= g, b /= g, c /= g;
  if (a < 0) a = -a, b = -b, c = -c;
  if (a == 0 and b < 0) b = -b, c = -c;
  return {a, b, c};
}

