    a--; b--;
    g[a].push_back({b,i});
    g[b].push_back({a,i});
  }
  vector<int> seq;
  vector<int> par(n,-1);
  vector<int> peg(n);
  {
    queue<int> q;
    par[0]=-2;
    peg[0]=0;
    q.push(0);
    while(!q.empty()){
      auto od=q.front(); q.pop();
      seq.push_back(od);
      for(auto &nx : g[od]){
        if(par[nx.first]==-1){
          par[nx.first]=od;
          peg[nx.first]=nx.second;
          q.push(nx.first);
        }
      }
    }
  }

  reverse(seq.begin(),seq.end());
  vector<int> sz(n,1);
  vector<ll> x(n,0);
  ll glob=0;
  for(auto &nx : seq){
    for(auto &ny : g[nx]){
      if(ny.first==par[nx]){continue;}
      sz[nx]+=sz[ny.first];
    }
    if(2*sz[nx]<n){
      glob+=peg[nx];
      x[nx]-=peg[nx];
    }
