#include<bits/stdc++.h>

using namespace std;
using ll=long long;
using pl=pair<ll,ll>;
using i128=__int128;

bool comp(const pl &l, const pl &r){
  return (((i128)l.first)*((i128)r.second) < ((i128)r.first)*((i128)l.second));
}

ll sgn(ll x){
  if(x>0){return 1;}
  else if(x<0){return -1;}
  return 0;
}

pl solve(vector<ll> a,vector<ll> b){
  ll n=a.size();
  vector<pl> vp;
  for(ll i=0;i<n;i++){
    if(a[i]<0){a[i]*=-1; b[i]*=-1;}
    if(a[i]>0){vp.push_back({b[i],a[i]});}
  }
  sort(vp.begin(),vp.end(),comp);

  pl x={1,1};
  ll ps=0,ss=0;
  for(auto &nx : vp){ss+=nx.second;}
  for(auto &nx : vp){
    ll s1=sgn(ps-ss);
    ps+=nx.second; ss-=nx.second;
    ll s2=sgn(ps-ss);
    if(s1*s2<=0){
      x=nx;
      break;
    }
  }

  pl res={0,x.second};
  for(ll i=0;i<n;i++){
    ll lef=a[i]*x.first;
    ll rig=b[i]*x.second;
    res.first+=abs(lef-rig);
  }

  ll g=gcd(res.first,res.second);
  res.first/=g;
  res.second/=g;
  return res;
}

